REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (1,'endfield','e001','term','high','超域','深度读数为1的时空，与现实空间重叠','[\"超域\", \"深度读数1\", \"亚空间\", \"热寂宇宙\"]','[\"超愈\"]','超域是对塔卫二星球内部、表面、大气及外层空间中所有深度读数为 1 的时空的统称。在塔卫二的时间尺度下，现实空间与超域存在重叠，物质与能量在两者之间的流动已被证实为可能。\n\n两者之间的阻隔有时会破溃，产生的空间通道叫「裂隙」，裂隙周边读数通常接近 0.5，因此附近是动态侵蚀的高发地点。种植源石或铺设活性源石能压低周边读数，从而在一定程度上遏制破溃，但这种效果没有固定规律。\n\n物质进入超域的后果随机而不可预测，生物维持生命相关的活动在其中会受到极大的阻滞与妨害；能量则以势能转化的形式单方向从超域流向现实空间，即使没有裂隙也会发生，速率超过阈值就容易引发不可控的爆炸。\n\n主流假说认为超域是另一片正在安静迈入热寂、遍布死亡之毒的宇宙，亚空间是隔开它与现实空间的隔膜。这套假说至今缺乏数学模型与实验观测支撑，人类对超域的理解仍然十分有限。',0,'2026-11-15 14:03:40.306086');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (2,'endfield','e002','term','high','侵蚀','会解离或反演物质与时间的有害现象','[\"侵蚀\", \"动态侵蚀\", \"静态侵蚀\", \"侵蚀潮\"]','[\"亲蚀\"]','侵蚀是对塔卫二星球内部、表面、大气及外层空间中存在的一系列成型的有害现象的统称，大体分动态侵蚀与静态侵蚀，后者一般被视为前者消退后的遗迹。\n\n典型的动态侵蚀——地面上的侵蚀流体、水体中的侵蚀潮——有极易辨认的光学特征，外表呈现诡异色彩。它以完全不定的速率，对接触、吞没的所有物体造成解离性破坏和／或反演性破坏，即从发生的时空中剥夺物质和／或时间。持续一段时间后（最短记录 217 毫秒，最长超过 149 年）会消退为静态侵蚀，常表现为附着在破坏残余物表面的一层沥青状流质。\n\n侵蚀幸存者常报告幻听、幻视与莫名的压力，尽管他们的脑部并未受侵蚀影响——脑部受侵蚀的受害者通常无法幸存。经百余年统计，动态侵蚀会在深度读数为正值的时空中随机发生，概率随读数从 0 到 1 大体构成一条钟形曲线。',0,'2026-11-15 14:03:40.307167');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (3,'endfield','e003','term','high','裂隙','现实与超域破溃形成的通道','[\"裂隙\", \"空间通道\", \"裂隙群\", \"裂隙带\"]','[\"裂缝\"]','裂隙是现实空间与超域之间的阻隔破溃后产生的空间通道；在罕见情况下，时间尺度也会被打乱。裂隙周围通常深度读数接近 0.5，这意味着它附近会成为动态侵蚀的高发地点。\n\n裂隙有大有小。武陵甚大裂隙是文明环带已探知范围内规模最大的侵蚀裂隙，在地理空间上呈网状分布，由一处极为活跃的裂隙主体和向周边延伸数十公里的分支裂隙带构成。\n\n对付裂隙的常规手段有两种：从外围向裂隙起始点逐层铺设源石隔离带，或用息壤类材料把裂隙与水体隔开。前者在武陵那种水文复杂、裂隙分布广的地方并不适用，后者是宏山科学院逼出来的另一条路。',0,'2026-11-15 14:03:40.307989');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (4,'endfield','e004','term','high','深度读数','衡量空间深度的0到1指标，1即超域','[\"深度读数\", \"读数0.5\", \"钟形曲线\", \"深度测量\"]','[\"深读\"]','深度读数是衡量空间「深度」的指标，取值 0 到 1：读数 1 的时空就是超域，读数接近 0.5 的地方容易发生动态侵蚀。\n\n它不是仪器上的一个装饰数字。种植源石、铺设活性源石能改变周边读数；超域活动活跃的区域，依赖源石技术的设备、器材都会受到较大影响，读数就是最先报警的那一项。\n\n动态侵蚀的发生概率随读数从 0 到 1 构成一条钟形曲线，这是百余年样本统计出来的结论，也是开拓队决定「这一段路能不能走」的主要依据。',0,'2026-11-15 14:03:40.308629');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (5,'endfield','e005','term','high','天使','由锚点催化、带光环结构的敌对可动实体','[\"天使\", \"锚点造物\", \"形成模式\", \"天使分类编码标准\"]','[\"天史\"]','天使是对由锚点催化形成、由自然物质构成并带有光环结构的所有敌对可动实体的统称，是塔卫二开拓历史至今人类方对抗的主要敌人，过去的「天使战争」正因它们得名。\n\n目前能明确的个体行为只有「形成」「解体」「模仿」以及「攻击人类／人造物」四种；它们自锚点形成的过程有明显的组装与制造特征，因此不能认定天使是一种生物、具有生命。一个天使个体的外表、移动方法和攻击手段的总合称为它的「形成模式」；同一锚点催化出的个体往往只有几类形成模式，偶尔出现非模式个体或变异种。\n\n自第一次天使战争以来，人们不断观测到新的形成模式，《天使分类编码标准》因此而生，用来快速查询某种天使的弱点与应对方法。今天的天使威胁以来源不明、被随机投掷的锚点造成的小规模袭击为主，但北方开拓区在第一次天使战争中不到 24 小时便全部被毁的记录还在。\n\n关键机制：不破坏锚点，天使还会不断出现。',0,'2026-11-15 14:03:40.309202');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (6,'endfield','e006','term','high','锚点','催化天使形成的关键物，多被随机投掷','[\"锚点\", \"锚点核心\", \"锚点投掷\", \"催化锚点\"]','[\"猫点\"]','锚点是催化天使形成的关键物。来源不明、被随机投掷到开拓区的锚点，造成了今天主要的小规模天使袭击；一个锚点「能形成哪几种模式的天使」是它的固有属性。\n\n锚点通常有核心，破坏核心才能让这一批天使停止出现。旧工厂区那次，锚点核心藏在地下实验室里，必须先清掉守着它的裂地者才能动手。\n\n有证据显示，裂地者可以在一定程度上掌握操控天使的技术：四号谷地袭击中，锚点有规律地出现在工团各站点上空，这不是巧合。',0,'2026-11-15 14:03:40.309760');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (7,'endfield','e007','term','high','协议源石','用复数源石搭起的传送网络','[\"协议源石\", \"传送网络\", \"协议石\", \"协议传送网\"]','[\"协义源石\"]','协议源石是终末地工业的核心技术成果之一。借助由协议源石搭建的传送网络，把人员与物资在物理距离相隔甚远的两点之间瞬时送达，不再只能依靠星门这样的「遗产」。\n\n抵达塔卫二后不久，许多研究团体注意到源石与超域能量彼此影响、进而干涉物理性质与空间连续性的现象；在管理员的带领下，终末地工业对此展开深入研究，诞生了名为「协议源石」的特殊产物，并找到了用复数协议源石搭建传送网络的方法。\n\n单次传送能承载的人员与物资量高度受限，还要调用具有高度危险性的超域能量，所以这项技术在问世阶段没有获得太多关注。第一次天使战争改变了一切：协议源石和传送网络的价值在这场生存之战里得到了验证。\n\n特种技术部门的干员通常配一枚协议源石辅助传送定位；帝江号的核心是一整块巨大的协议源石。',0,'2026-11-15 14:03:40.310303');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (8,'endfield','e008','term','high','协议核心','集成工业系统的基础装置','[\"协议核心\", \"集成核心区域\", \"次级核心\", \"部署协议核心\"]','[\"协议核芯\"]','协议核心是协议源石技术的终极形态，也是集成工业系统的基础。只要还有能源，它就能从零在荒野上构建一套完整的工业体系。\n\n部署协议核心之后，该地即成为「集成核心区域」，开始建立协议传送网络；一个区域往往先落一个主核心，再按需要铺次级核心，把电力、物流和生产线一段段接起来。\n\n协议核心的实地部署权限在管理员手上。四号谷地、武陵城的行动里，第一件事几乎都是「把核心放下去」——放下去，才有电、有传送、有得守。',0,'2026-11-15 14:03:40.310852');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (9,'endfield','e009','term','mid','协议空间','与管理员的源石能力相关的空间现象','[\"协议空间\", \"协议奇点\", \"异常协议空间\", \"协议空间入口\"]','[\"协议空问\"]','协议空间是与管理员的源石能力相关的空间现象，可用于定位与进入特定空间。常规协议空间入口的数据是杂乱的；如果扫描结果呈现规则的曲线，那多半是人为做出来的。\n\n四号谷地休息站北侧约一公里处曾发现过一个人为痕迹极强的协议空间入口，秦茳尺等人对此极为警惕。\n\n只有管理员能自由进入协议空间——这是莱万汀的说法，也是环带里少数被反复验证过的「特权」。',0,'2026-11-15 14:03:40.311635');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (10,'endfield','e010','term','high','集成工业系统','把生产线小型化，现场就能搭起来','[\"集成工业系统\", \"自动化生产线\", \"模块化生产\", \"现场部署\"]','[\"集成工叶\"]','集成工业系统是终末地工业掌握的关键核心技术之一：生产设备小型化、模块化，只需在现场部署少量人力，就能在极短时间内搭起一套功能完整的自动化生产线。\n\n这套理念早在拓荒者从泰拉出发之前就被提出过——比起用移动平台搬运整条生产线，打包模块化的设施、按需灵活部署，被认为是源石工业未来生产方式的高级形态。\n\n为了把它变成现实，终末地投入了大量研发资源，并在与联盟工团合作的枢纽区基地经过多年测试与反复迭代，最终满足了绝大多数生产功能需求。现在，系统的实地调用权限已交付给管理员。\n\n总工程师安德烈说过一句近乎愿景的话：这套系统全部完成之后，塔卫二上就不再有所谓的「开拓区」了。',0,'2026-11-15 14:03:40.312346');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (11,'endfield','e011','term','high','息壤','能中和液态侵蚀的新型源石材料','[\"息壤\", \"重息壤\", \"息壤粒子\", \"新型源石材料\"]','[\"息囊\"]','息壤是一种用于遏制侵蚀的新材料，是宏山科学院在武陵科学发展区的主要科研成果之一。活性化的息壤能够消耗自身，把液态侵蚀逐步中和为自然水体。\n\n它诞生于宏山科学院在武陵区的综合治理项目。武陵水文复杂、裂隙分布广、侵蚀以液态为主，环带惯用的「从外围向裂隙起始点逐层铺设源石隔离带」在这里不适用，天师们于是借宏科院独有的巨兽学优势另辟蹊径。\n\n塔罗斯历 140 年，在一众天师与一位巨兽代理人的共同努力下，息壤问世；终末地工业参与了原型息壤设施的建造。如今以息壤为基础的天师桩阵列和大规模净水工程，在武陵甚大裂隙正上方造出了一片净土。\n\n重息壤是它的强化形态，用于修复天师桩阵列核心一类的关键节点。',0,'2026-11-15 14:03:40.313072');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (12,'endfield','e012','term','high','天师桩','立柱式息壤装置，阵列可压制侵蚀潮','[\"天师桩\", \"首墩\", \"阵列核心\", \"辅桩\"]','[\"天师庄\"]','天师桩是一种用于遏制侵蚀潮的立柱式息壤装置，是宏山科学院在武陵科学发展区的主要科研成果之一。\n\n北部禁区的灾难之后，天师们放弃了「集中息壤强行闭合甚大裂隙」的思路，转为对侵蚀潮做针对性治理，天师桩就是在这个思路下诞生的载体。塔罗斯历 143 年，武陵的第一根天师桩「首墩」投入试运行。\n\n日常运转时，天师桩阵列持续向大气和水体散布息壤粒子，阻止裂隙把更多水体转化为液态侵蚀；侵蚀潮袭来时，环境中的息壤粒子被活性化，形成一道削弱潮势、扭转液态侵蚀的边界。\n\n经过十年扩建升级，武陵城周边的阵列已把侵蚀灾害控制住，除每四个月一次的汛期外，侵蚀潮平日里不再威胁城内的生产生活。',0,'2026-11-15 14:03:40.313679');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (13,'endfield','e013','term','mid','枢壤仪','庄方宜牵头的息壤装置项目','[\"枢壤仪\", \"弃剑台\", \"息壤产能\"]','[\"枢壤义\"]','枢壤仪是宏山科学院由息壤新材项目负责天师庄方宜牵头的一项装置项目，目标直指武陵甚大裂隙本身。\n\n塔罗斯历 142 年的大规模侵蚀灾害后，武陵的息壤储备短缺，枢壤仪在数次迭代后仍远未达到预期，项目被暂时中止，研究重点转向息壤生产迭代与天师桩阵列建设。\n\n塔罗斯历 152 年，在终末地工业的协助下，息壤产能窘迫的困境有所缓解，为了解决甚大裂隙这一威胁，枢壤仪项目得以重启。弃剑台是与之相关的强化作业点。',0,'2026-11-15 14:03:40.314238');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (14,'endfield','e014','term','high','巨兽','泰拉原生的超巨型生物','[\"巨兽\", \"祖灵之父\", \"萨米巨兽\", \"巨兽学\"]','[\"巨售\"]','巨兽是原生于行星泰拉的超巨型生物。已知个体的躯体规模从最小数百米到最大数十万米不等；它们仅仅存在，就足以改写自然规律、重塑星球环境，甚至孕育崭新的生命形态。\n\n所有已知巨兽都具备远超现代源石技艺理论范畴的独特权能，其中最为人类熟知的是塑造自身「代理人」的能力。\n\n宏山科学院所属的炎国是泰拉诸国中对巨兽研究最深的国家，历史上曾与巨兽爆发战争；如今宏科院是文明环带的「巨兽学专家」，掌握巨兽学识，与巨兽代理人维持着谨慎而平稳的关系，并把巨兽权能投入技术研发——息壤就是这一领域最重要的成果。',0,'2026-11-15 14:03:40.314795');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (15,'endfield','e015','term','mid','代理人','巨兽权能的具现，与人类沟通的渠道','[\"代理人\", \"巨兽代理人\", \"司岁台秉烛\", \"秉烛人\"]','[\"代里人\"]','与泰拉人类形态相近的「代理人」是巨兽与泰拉文明展开沟通的渠道，也是巨兽权能的具现。许多代理人个体行走大地数百年而从未被人类察觉。\n\n应龙特勤队队员装备的巨兽造物，就是天师改造过的巨兽产物，能让人在一定程度上借用巨兽的力量。\n\n炎国司岁台一类的机构与代理人打过上百年交道；息壤的问世，也是天师与一位巨兽代理人共同努力的结果。',0,'2026-11-15 14:03:40.315322');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (16,'endfield','e016','term','high','再旅者','从信息碎片析出到塔卫二的人','[\"再旅者\", \"记忆原型\", \"信息碎片\", \"森林脉络\"]','[\"在旅者\"]','再旅者是终末地工业人事档案里一批特殊的干员：他们普遍留有一份保密级别极高的额外卷宗，持有与终末地高级管理人员直接通讯的权限，名义上是依据《终末地工业与罗德岛制药公司关于特种技术岗位合作的框架协议》从罗德岛来的派遣人员，实际并不常在终末地的设施内工作。\n\n成因是那枚穿越星门来到塔卫二的「最初的源石」在第一次天使战争最后决战中受到污染，性质退化；混乱的内化宇宙里仍留下一些完整的信息碎片。在管理员本人与 M3 的默许下，罗德岛时任领袖华法琳对被污染的源石展开抢救性研究，一枚碎片的深度读数意外自发上升，从内化宇宙「析出」到现实空间。\n\n第一位再旅者抵达塔卫二其实是个意外。再旅者们走出源石森林后普遍对罗德岛和管理员表现出友好、合作的态度；他们清楚自己是一个独立的人，只是对「记忆原型」在泰拉的一部分人生与人际关系有所认识，也因此带着「曾经」的技能。\n\n华法琳后来找到了与信息碎片交流的方法，主动探索源石森林，接回那些愿意来塔卫二的碎片，并为他们设计了整套进入这个世界的流程。',0,'2026-11-15 14:03:40.315830');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (17,'endfield','e017','term','high','基石','掌握先史遗产的特殊个体','[\"基石\", \"先史文明遗产\", \"四十英杰\", \"前文明残渣\"]','[\"机石\"]','基石是掌握了先史文明遗产的特殊个体，其存在本身就是遗产的一部分。按终末地 S.O.W. 关键敏感情报安全协议的口径：基石对泰拉联合科考团的全面袭击引发了第一次天使战争，其摧毁、奴役泰拉文明的敌对意图无比明确。\n\n基石是锚点与天使的创造者，但这两者只是它最基本的「工具」，它真正的造物远比这些更危险。\n\n塔罗斯历 15 年，管理员与四十英杰在北极取得了决定性胜利，基石的威胁被解除，这场胜利是终结第一次天使战争的关键。\n\n「前文明的残渣」是聂菲斯对基石一类存在的蔑称；她不承认自己会向这样的东西俯首。',0,'2026-11-15 14:03:40.316337');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (18,'endfield','e018','term','high','星门','连接泰拉与塔卫二的遗产通道，已崩溃','[\"星门\", \"遗产\", \"穿星门\", \"星门崩溃\"]','[\"星們\"]','星门是连接泰拉与塔卫二的「遗产」。一百五十二年前，来自泰拉的拓荒者重启星门，初次踏足这颗卫星。\n\n星门崩溃后，塔卫二与泰拉的联系断绝了一个多世纪，环境资源成为人们自谋出路的关键；经过几代人的开拓，失落于新世界的拓荒者才站稳脚跟。\n\n协议源石的传送网络之所以重要，正是因为它让「瞬时送达」不再只能依赖星门这样的遗产。塔卫二上关于星门的一切，都同时是技术问题与政治问题。',0,'2026-11-15 14:03:40.316839');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (19,'endfield','e019','term','high','环带公约','塔罗斯历17年签订的根本协定','[\"环带公约\", \"公约\", \"U3\", \"三大阵营\"]','[\"环代公约\"]','《环带公约》是全文明环带的根本性协定，塔罗斯历 17 年签订，也是文明环带得以成立的基础。它不接受自我宣称为「国家」的实体加入，只承认阵营、团体与组织。\n\n要点包括：严格限制现实空间与超域之间的物质交换实验，绝大部分相关活体实验被禁止；要求各方尽可能救助受灾群体；保障矿石病感染者权益；规定协调调度券发行与物资储备；缔约方可在危机时正式重启终末地工业的全文明环带特别权限。\n\n联盟工团、环塔商会、宏山科学院因公约地位合并称为 U3，也叫「三大阵营」「三巨头」。终末地工业也是环带重要成员，帝江号上设有供各方讨论公约修订的会场。\n\n在裂地者口中，公约是「他们捏造的谎言」；在环带居民口中，它是悬崖边勒住缰绳的那只手。',0,'2026-11-15 14:03:40.317375');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (20,'endfield','e020','term','mid','调度券','公约认可的物资调配与风险保障凭证','[\"调度券\", \"谷地调度券\", \"物资调度\", \"调配机制\"]','[\"调渡券\"]','调度券是《环带公约》认可的物资调配与风险保障机制，用于授权后的区域物资协调与兑换。它只在被授权的区域内有效，一张券绑定一个区域——四号谷地只能用谷地调度券。\n\n投入更多调度券可以升级一个地区的物资调度系统，解锁更多种类的货物与更高的调配能力。它是协调手段，不阻碍正常的经济活动。\n\n如果有人拿它囤货居奇，那性质就不一样了。终末地的物资调度员会明确告诉管理员：发现这种情况务必告知，剩下的由他们处理。',0,'2026-11-15 14:03:40.317859');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (21,'endfield','e021','term','low','折金票','民生经济中正常流通的票券','[\"折金票\", \"金票\", \"民生货币\", \"邮费\"]','[\"折金卷\"]','折金票是塔卫二民生经济中正常流通的票券，日常买卖、邮费、雇佣短工都认它。\n\n它和调度券不是一回事：折金票是钱，调度券是授权与配额。环带里有人抱怨「几本笔记邮到玛尔斯波利斯收五百金票」，说的就是折金票的购买力。\n\n在开拓区，折金票也常被当作「欠条」以外的第二选择——毕竟纸会烂，票不会。',0,'2026-11-15 14:03:40.318391');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (22,'endfield','e022','term','high','矿石病','源石引发的疾病，感染者受公约保障','[\"矿石病\", \"感染者\", \"矿石病抑制剂\", \"源石病\"]','[\"矿右病\"]','矿石病是源石引发的疾病。感染者体内脏器轮廓模糊、可见异常阴影，循环系统内源石颗粒检测异常；病程不可逆，需要长期抑制。\n\n《环带公约》保障矿石病感染者的权益，医疗部门对在册感染者长期供应矿石病抑制剂。制度上不许歧视，现实里歧视仍在，尤其在开拓区。\n\n汤汤十年前的冲突里感染，十年没接受过特殊治疗，只靠寨民的土方子，检查结果却控制得相当好——她自己说「他们都说我是河流的女儿，水会把疾病带走」。医生批注得很干脆：不可能。\n\n抑制剂不是万能药。清波寨有人把药砸回天师脸上，喊着不要武陵人的施舍——药能续命，续不了仇。',0,'2026-11-15 14:03:40.318887');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (23,'endfield','e023','term','high','源石','文明能源与技艺媒介，也会致矿石病','[\"源石\", \"活性源石\", \"源石技艺\", \"源石工业\"]','[\"原石\"]','源石是塔卫二的能源与工业基础，也是源石技艺的媒介。种植源石、铺设活性源石能有效降低周围空间的深度读数，从而遏制超域的破溃，但效果缺乏固定规律，有时源石的活性反而会被裂隙抑制。\n\n源石工业是环带的生产方式：移动平台、精炼炉、供电桩、铳械塔，都建在这套材料学上。集成工业系统之所以能把生产线做小，前提也是源石设备的小型化。\n\n源石与矿石病的关系是塔卫二社会最敏感的一条线：它给了文明动力，也给了文明一个长期无法治愈的病人。',0,'2026-11-15 14:03:40.319324');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (24,'endfield','e024','term','high','泰拉','塔卫二人的来处与巨兽的原生行星','[\"泰拉\", \"泰拉文明\", \"星门彼岸\", \"来处\"]','[\"泰垃\"]','泰拉是塔卫二人的来处。一百五十二年前，拓荒者从泰拉穿过星门来到塔卫二；巨兽也是原生于泰拉的超巨型生物。\n\n泰拉不是塔卫二的一个国家，也不是可以随时回去的后方——星门崩溃后，联系断绝了一个多世纪。关于泰拉的记忆，在这里更多是技术遗产、家族传说和一种说不清的乡愁。\n\n写塔卫二时，泰拉只作为历史前提与来源地出现，不要把泰拉的国别政治、社会结构整套搬过来当塔卫二的设定。',0,'2026-11-15 14:03:40.319788');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (25,'endfield','e025','term','high','裂地者','在文明缝隙里靠暴力侵占谋生的武装团体','[\"裂地者\", \"匪帮\", \"军阀雅各布\", \"武装掠夺者\"]','[\"列地者\"]','「裂地者」多数情况下指在文明的狭缝里生存、依靠暴力侵占行为谋生的武装掠夺者团体。它是在塔卫二独立诞生的概念。\n\n起源是拓荒者抵达后的第五十九年：荒地军阀雅各布·迈森把手下的匪帮命名为「裂地者」。这位曾经的天使战争英雄带人占据了一片源石培植地，建立了塔卫二有史以来最危险的武装掠夺者团体。即使他和他的裂地者被文明环带剿灭，人们仍沿用这个词，概括那些蔑视文明秩序的匪帮武装分子。\n\n雅各布的匪帮覆灭后，碾骨、狼群、沙盗三大氏族继承了军阀的遗产，各自对文明环带的态度不同。除此之外，还有许多规模更小、名不见经传的裂地者团体同时在这颗星球上活动。',0,'2026-11-15 14:03:40.320239');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (26,'endfield','e026','term','high','碾骨氏族','最暴力的裂地者氏族，聂菲斯以雾火统合','[\"碾骨\", \"碾骨氏族\", \"雾火\", \"氏族印记\"]','[\"碾古\"]','碾骨是裂地者三大氏族中最暴力的一支，继承了军阀雅各布留下的巢雕。巢雕林立，往往代表碾骨即将对附近区域发动大规模攻击。\n\n碾骨的崛起有一个关键：一种被称作「雾火」的火焰。它似乎与侵蚀有关，除了致幻性与神经毒性，还能在一定时间内大幅强化摄入者的身体机能。围绕雾火，碾骨建立起了比其他裂地者氏族更强大、更坚实的组织——带来雾火的人，是他们的头领聂菲斯。\n\n聂菲斯改变了碾骨「只接触巢雕这种传承下来的巫术装置」的旧作风，让部众尝试吸收侵蚀、崇拜超域；狼卫把这称作前所未见的疯狂举动。氏族内部并非铁板一块，旧派与「赐福」派的裂痕一直存在。',0,'2026-11-15 14:03:40.320723');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (27,'endfield','e027','term','mid','狼群氏族','重秩序、与环带温和的裂地者氏族','[\"狼群\", \"狼群氏族\", \"头狼\", \"孤高猎手\"]','[\"狼群氏旅\"]','在裂地者普遍被视作「秩序破坏者」的当下，重视秩序、对文明环带持温和态度的狼群氏族是异类中的异类。他们至今固守着某些古老传统，譬如家族文化与崇尚团结。\n\n这份特殊性让本就与他们对立的碾骨更加仇视这些行走在荒地上的孤高猎手。十几年前，碾骨对刚失去头狼、正处于薄弱期的狼群发动过一次截杀，重创了氏族。\n\n狼卫是那场劫难的亲历者，与妹妹洛茜一同幸存。他后来离群，以寻求合作为由找上终末地——理由是「我希望为狼群寻找到另一个未来，而终末地拥有让这件事成真的可能」。',0,'2026-11-15 14:03:40.321222');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (28,'endfield','e028','term','low','沙盗氏族','继承军阀遗产的三大裂地者氏族之一','[\"沙盗\", \"沙盗氏族\", \"三大氏族\", \"匪帮遗产\"]','[\"沙道\"]','沙盗是与碾骨、狼群并列的三大裂地者氏族之一，同样继承了军阀雅各布·迈森的遗产。\n\n与碾骨的高调、狼群的孤高不同，沙盗在环带的公开记录里留下的多是零散的传说与出版物八卦——有人甚至怀疑某些污蔑英雄的非法读物出自沙盗之手，当然这话没人敢当面说。\n\n三个氏族看待自身与文明环带关系的方式各有不同，这也是环带能对裂地者分而治之的缝隙。',0,'2026-11-15 14:03:40.321710');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (29,'endfield','e029','term','mid','巢雕','碾骨散播侵蚀烟雾的战地设施','[\"巢雕\", \"巫术装置\", \"烟雾\", \"巢雕林立\"]','[\"巢碉\"]','巢雕是碾骨氏族的标志性战地设施。在裂地者尚未分裂的时代，军阀雅各布从塞什卡带出了一种巫术装置——巢雕。它能吸收侵蚀物质，并以雾状散播出去。\n\n巢雕立起、烟雾弥散时，范围内一切基于源石技术的设备都会受到明显干扰，包括无人机、通信设备与交通工具。碾骨把巢雕当作掩护袭击和掠夺的战略设施使用。\n\n如今的巢雕经聂菲斯改造，碾骨成员在其影响范围内能得到作战能力强化；常人吸入「烟雾」后，从呼吸道开始会感到明显不适，并有一定概率出现幻听、幻视。',0,'2026-11-15 14:03:40.322225');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (30,'endfield','e030','term','high','天师','宏山科学院的正式科研技术人员','[\"天师\", \"天师府\", \"天师府学院\", \"司岁台\"]','[\"天師\"]','「天师」在如今的塔卫二，只代表一种身份：宏山科学院的正式科研技术人员。炎国古话里赋予这个词的许多特殊含义，在这里被压成了一条职业定义。\n\n天师职称承炎制，按专业门类划分。天师府学院设在有一定规模的科学发展区，教研一体，为宏科院乃至整个文明环带培养新的天师；只要向宏科院证明自己的能力，不是炎国后裔也能入学修习。\n\n塔卫二的天师把研究领域倾向文明环带的生存危机：裂隙、侵蚀、息壤、巨兽学、净水与农业。武陵城的人口主体就是天师、职农、职工及他们的家属。',0,'2026-11-15 14:03:40.322681');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (31,'endfield','e031','term','mid','应龙特勤队','借巨兽造物作战的特种部队','[\"应龙\", \"应龙特勤队\", \"巨兽造物\", \"重度侵蚀作战\"]','[\"应龍\"]','应龙特勤队的成立，基于《环带公约》赋予缔约各方建立并维持用于保卫文明环带整体的军事力量这一共同原则。塔罗斯历 23 年，一位资深的炎国司岁台秉烛人从第一次天使战争的炎国老兵中，遴选并训练了第一批队员。\n\n宏科院在应龙身上毫无保留地投入了战火中留存的炎国先进技术。队员装备经过天师改造的巨兽造物，能在一定程度上利用巨兽的力量，是文明环带中极少数能在重度侵蚀影响环境下执行长时间作战任务的特种部队。\n\n应龙关由宏科院的土木天师设计，所有建造标准都基于一个假想场景：甚大裂隙再度爆发。必要时，宏科院会调用最高规格的应急力量，借巨兽权能进一步强化关隘防御。',0,'2026-11-15 14:03:40.323359');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (32,'endfield','e032','term','mid','前文明','塔卫二上早于拓荒者的文明遗产','[\"前文明\", \"先史文明\", \"遗迹\", \"技术遗产\"]','[\"前文名\"]','前文明（先史文明）是塔卫二上早于泰拉拓荒者的文明遗产，其存在本身就是一连串未解的技术谜题：无法复现的材料、远超当代理解的构造，以及「基石」这种活着的遗产。\n\n寂语修会一个多世纪以来的主要工作之一，就是调查与发掘塔卫二可能存在的前文明遗迹；藏剑谷的秘库传说埋着第一次天使战争前遗留的技术遗产。\n\n阿伯莉采石场挖到的那枚金属结构物体被命名为「阿伯莉之石」——远超人类当前技术理解，采石场因此停工。',0,'2026-11-15 14:03:40.323879');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (33,'endfield','e033','term','mid','塔罗斯历','塔卫二通用纪年，元年为拓荒者抵达','[\"塔罗斯历\", \"纪年\", \"塔罗斯历152年\", \"编年\"]','[\"塔罗丝历\"]','塔罗斯历是塔卫二通用的纪年方式，元年对应拓荒者重启星门、初次踏足这颗卫星的那一年；当前叙事时间大致在塔罗斯历 152 年前后。\n\n几个可以钉住的年份：塔罗斯历 5 年至 15 年是第一次天使战争；17 年《环带公约》签订；132 年宏科院科考团进驻武陵；140 年息壤问世；142 年武陵科考站灾难；143 年首墩投入试运行；152 年枢壤仪项目重启。\n\n更早的文献里「天使战争」与第一次天使战争指的是同一场战争；塔罗斯历 142 年之前的记述需要按这个口径读。',0,'2026-11-15 14:03:40.324339');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (34,'endfield','e034','term','high','开拓区','文明环带之外待清理与建设的区域','[\"开拓区\", \"清场\", \"开拓行动\", \"前进基地\"]','[\"开托区\"]','开拓区是文明环带之外的土地：风沙、废墟，和仍在活动的东西。它不是一个行政区，而是一种状态——还没被清理、还没被接通、还没被写进配给表。\n\n在开拓区，一切以「能不能活下来」排序：先清天使与锚点，再铺电与传送，再修路、建据点、接难民。联盟工团的前进基地就是从工业母舰「城市母亲」的船坞里一艘艘驶出来的。\n\n环带人把开拓区当成机会与流放地的混合体；开拓区的人则只认一件事——今天有没有人把名字从名单上划掉。',0,'2026-11-15 14:03:40.324789');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (35,'endfield','e035','term','mid','环带居民','有环带认可身份、住在管治区内的人','[\"环带居民\", \"环带身份\", \"配给\", \"管治区\"]','[\"环代居民\"]','具有文明环带认可的身份、居住在环带各阵营、团体、组织管治的处所中的人，被称为「环带居民」。在塔卫二总人口中，环带居民占九成以上。\n\n身份意味着配给、医疗、调度券的资格，也意味着受公约约束：带武器进城要报备，做超域实验要批文，欠了商会的账要还。\n\n剩下不到一成的人分布在开拓区、裂地者聚落与各路流动人口里。他们没有环带身份，也就没有那张配给表——这是塔卫二最硬的一道分界线。',0,'2026-11-15 14:03:40.325277');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (36,'endfield','e036','term','low','阿伯莉之石','采石场挖出的超时代金属结构物','[\"阿伯莉之石\", \"神秘金属\", \"采石场停工\", \"阿伯莉采石场\"]','[\"阿伯丽之石\"]','阿伯莉之石是四号谷地阿伯莉采石场挖掘到的一件金属结构物体，远超人类当前的技术理解。采石场因此被下令停工，那件东西也就以采石场的名字命名。\n\n采石场本身的名字来自塔罗斯历 75 年为保护学生而牺牲的教师阿伯莉；联盟工团把即将竣工的采石场命名为「阿伯莉采石场」以作纪念。\n\n这类「挖出来但看不懂」的东西，是塔卫二前文明线索的典型形态：没有说明书，只有后果。',0,'2026-11-15 14:03:40.325849');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (37,'endfield','e037','term','low','遗物与残骸','战场上可回收的天使残骸与前文明遗物','[\"遗物\", \"天使残骸\", \"沉积酸\", \"拾荒\"]','[\"遗物残骇\"]','塔卫二的战场会留下东西：天使的残骸、旧文明的构件、失效的协议装置。拾荒者与工团的回收队靠这些东西吃饭，科研部门靠它们反推天使的弱点。\n\n首墩一带的地形曾堆积大量天使残骸，佩丽卡通过「沉积酸」判断出这一点——残骸堆积会改变土壤与地下水，这是判断一片区域打过什么仗的土办法。\n\n遗物不总是安全的。被超域覆盖过的物质会成为侵蚀现象的源头，捡之前先测读数，是回收队的第一条规矩。',0,'2026-11-15 14:03:40.326375');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (38,'endfield','e038','place','high','塔卫二','塔罗斯的宜居卫星，故事主舞台','[\"塔卫二\", \"Talos-II\", \"塔罗斯的卫星\", \"宜居卫星\"]','[\"塔卫贰\", \"塔维尔\"]','塔卫二是气态巨行星「塔罗斯」的天然卫星之一。一百五十二年前，来自泰拉的拓荒者重启星门，初次踏足这颗卫星。\n\n它巍峨的群山、交错的水体与繁盛的植被群落孕育了一个颇为完整的生态圈。在星门崩溃、与家园联系断绝的一个多世纪里，这里的环境资源是人们自谋出路的关键；经过几代人的开拓，拓荒者最终站稳脚跟，建立了新的文明家园。\n\n观测显示，塔卫二的公转轨道内外分布着数量未知的小型卫星，可宜居的只有它一个。由于独特的轨道位置与星门这样的「遗产」存在，文明环带认为这颗卫星的宜居环境并非宇宙的意外馈赠。',0,'2026-11-15 14:03:40.326870');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (39,'endfield','e039','place','mid','塔罗斯','塔卫二所环绕的气态巨行星','[\"塔罗斯\", \"气态巨行星\", \"母星\", \"行星系统\"]','[\"塔罗丝\"]','塔罗斯是一颗气态巨行星，也是塔卫二所环绕的母星。站在塔卫二的地表抬头，能看到它高悬于顶。\n\n「塔罗斯历」的纪年名就来自它；塔卫二的公转轨道内外散布着数量未知的小型卫星，塔罗斯是这一切的中心。\n\n塔罗斯本身没有被详细勘察过——对塔卫二的人来说，它更像一个每天都能看见、却始终够不着的地标。',0,'2026-11-15 14:03:40.327421');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (40,'endfield','e040','place','high','帝江号','终末地工业的轨道母舰总部','[\"帝江号\", \"O.M.V.\", \"母舰\", \"舰桥\", \"轨道飞行器\"]','[\"帝江號\", \"帝江\"]','帝江号（O.M.V.）是一艘位于塔卫二静止轨道上的飞行器，是终末地工业的总部，也是塔卫二唯一的轨道飞行器。\n\n随着星门崩溃、第一次天使战争爆发，人类失去与泰拉的联系，联盟工团、宏山科学院、环塔商会等推动了一批研究项目，帝江号正是其中之一。终末地联合各方，用诸多不可再生的珍贵技术资源，在轨道上完成了这座无法复现的奇迹。\n\n帝江号以一块巨大的协议源石为核心，承担总控协议系统运转的重任，支持协议传送、集成工业系统等各项功能；舰桥是调度与瞭望的地方，也是干员们口中「家」的客厅。\n\n帝江号上设有供环带成员讨论公约修订的会场，因此它同时是终末地的总部与文明环带的中立客厅。',0,'2026-11-15 14:03:40.328010');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (41,'endfield','e041','place','high','文明环带','公约体系下的人类集合体，占人口九成','[\"文明环带\", \"环带\", \"人类集合体\", \"环带范围\"]','[\"文明环帶\"]','文明环带是对在《环带公约》体系下、遵守相关规约的人类集合体的称呼。它由大大小小的阵营、团体、组织构成，由于公约限制，不接受自我宣称为「国家」的实体加入。\n\n它以公约为准绳，推行成员间的技术分工与自治，维持人类在塔卫二的基本生存，争取人类的自我实现。最大的三个阵营是联盟工团、环塔商会与宏山科学院，合称 U3；终末地工业也是重要成员。\n\n环带不是一块连续的地皮，而是由管治区、据点、航线和办事处连起来的一张网。网外就是开拓区，网眼破了，风沙和天使就从那里进来。',0,'2026-11-15 14:03:40.328594');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (42,'endfield','e042','place','mid','枢纽区','四号谷地的前线枢纽，终末地与工团共管','[\"枢纽区\", \"枢绿区\", \"枢纽区基地\", \"中控塔\"]','[\"枢钮区\"]','枢纽区是四号谷地一带的前线枢纽，也是终末地与联盟工团合作多年的基地所在，集成工业系统就在这里经过测试与迭代。\n\n基地有中控塔、制造舱、会客室、旧工厂区、军械库与源石副产物中心；中控塔是指挥与通讯的核心，基解围一役里，伤员也都集中在那里。\n\n枢纽区与帝江号之间的联络一旦中断，就说明地面上出了大事——基地解围就是从一次失联开始的。',0,'2026-11-15 14:03:40.329135');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (43,'endfield','e043','place','high','四号谷地','第一章主舞台，灾后重建中的开拓谷地','[\"四号谷地\", \"谷地\", \"四号谷地要塞\", \"谷地全境\"]','[\"四號谷地\"]','四号谷地是第一章的主舞台，一片曾遭重灾、正在重建的开拓谷地。枢纽区、旧工厂区、供能高地、矿脉源区、源石研究园、谷地要塞都在这片区域里。\n\n谷地的开拓史绕不开「世代摇篮」：管理员在矿脉源区种下的源石大树，养活了四号谷地最初几代人。约二十年前，代号「星体」的巨大天使袭击谷地，工团只能引爆源石大树，用它的能量毁掉「星体」。\n\n如今的四号谷地仍在恢复：大量地方没恢复联系，裂地者趁乱渗透，锚点规律坠落，侵蚀引发的问题一桩接一桩。',0,'2026-11-15 14:03:40.329851');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (44,'endfield','e044','place','mid','谷地要塞','四号谷地的要塞，曾被裂地者攻陷','[\"谷地要塞\", \"桥头工事\", \"要塞上层\", \"要塞通道\"]','[\"谷地要賽\"]','谷地要塞是四号谷地的军事支点，有桥头工事、升降桥与通往要塞上层的电梯。前往要塞的路要先修桥、给供电终端供电。\n\n基地解围期间，要塞遭裂地者袭击，碾骨氏族攻陷要塞、俘虏工团成员；决战就在要塞里打响，罗丹负责拦截，聂菲斯最终现身。\n\n要塞失守过一次，这件事在工团内部被反复提起——它不是一座建筑，是一条「能不能守住」的底线。',0,'2026-11-15 14:03:40.330467');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (45,'endfield','e045','place','mid','供能高地','四号谷地的能源区，藏有天然稳定裂隙','[\"供能高地\", \"源石发电站\", \"天然稳定裂隙\", \"高地\"]','[\"供能高台\"]','供能高地是四号谷地的能源区，源石发电站与超域试验场都在这里。高地拥有一条「天然稳定裂隙」——较长时间内未观察到扩张变化、不易引发侵蚀的裂隙。\n\n正因为这条裂隙，工团在这里搭起超域试验场；四号谷地开拓规划阶段，曾有科学家提议把整片高地建成集探索、研究、应用于一体的超域技术研究所，意见迟迟未被采纳。直到进行了近二十年的开拓建设，工团才把谷地环境评估为安全，解除高地北部的封锁。\n\n第一章后期，管理员一行人在高地与巢雕、碾骨主力反复拉锯，最终进入超域试验场做个了断。',0,'2026-11-15 14:03:40.331097');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (46,'endfield','e046','place','mid','矿脉源区','四号谷地的源石矿区，世代摇篮所在地','[\"矿脉源区\", \"蚀崖\", \"大树根须\", \"矿脉\"]','[\"矿脈源区\"]','矿脉源区是四号谷地的源石矿区，源石大树「世代摇篮」就长在它的深处，蚀崖观测站也设在这一带。\n\n这里的矿脉养活了谷地最初的工业：人们截取大树枝叶，建起第一座发电站与第一座采石场，让开拓计划进入正向循环。\n\n矿脉源区的地下并不安静。天使残骸、旧装置与侵蚀痕迹混在矿层里，采矿队与回收队经常要在同一段坑道里各干各的。',0,'2026-11-15 14:03:40.331780');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (47,'endfield','e047','place','mid','源石研究园','四号谷地的研究设施群，伊冯在此工作','[\"源石研究园\", \"研究园\", \"园区\", \"实验区\"]','[\"源石研究員\"]','源石研究园是四号谷地的一片研究设施群，终末地的技术干员与工团的研究员在这里做源石、侵蚀与超域相关的工作。伊冯的研究与试验组件多半出自这里。\n\n园区的实验区有严格的进出登记，超域相关的测试要在特定舱室或隔离区做；园区外围常能看到被清过又长回来的天使残骸堆。\n\n第一章「神秘信号」中，管理员先到研究园找伊冯，再按她的指引去两座协议通讯信号塔取扫描数据。',0,'2026-11-15 14:03:40.332319');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (48,'endfield','e048','place','mid','世代摇篮','矿脉源区深处的源石奇观，四号谷地之母','[\"世代摇篮\", \"源石大树\", \"星体\", \"星体残骸\"]','[\"世代搖篮\"]','世代摇篮是位于矿脉源区深处的源石奇观遗迹。四号谷地开拓初期能源严重不足，管理员在矿脉源区种下了一棵源石大树；人们截取大树枝叶，建起第一座发电站与第一座采石场。\n\n约二十年前，代号「星体」的巨大天使袭击四号谷地，种种对抗措施都失败后，联盟工团只能引爆源石大树，用其释放的巨大能量毁灭「星体」。\n\n源石大树如今仅剩树根，失去快速形成源石簇的能力，工人们仍称它为「世代摇篮」，感谢它养育了谷地数代人。最近的四号谷地袭击事件中，「星体」成百上千条肢体里的三根在锚点激活下重新组合为代号「三位一体」的天使，于世代摇篮再次被管理员击败。',0,'2026-11-15 14:03:40.332783');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (49,'endfield','e049','place','mid','北极点','序章战场，第一次天使战争的终局遗址','[\"北极点\", \"远征尽头\", \"巨塔\", \"巨兽之臂\"]','[\"北極点\"]','北极点（远征尽头）是序章的战场，也是第一次天使战争终局的遗址。塔罗斯历 15 年，管理员与四十英杰在这里取得决定性胜利，基石的威胁被解除。\n\n远征队跨越阻碍、穿过峡谷与花圃、越过「英雄的臂膀」、进入「过去」，最终在终点击败埃尔埃格尼斯、唤醒生命。\n\n这里的一切都巨大得不像人类造物：巨塔、花圃、巨兽残余的肢体。序章走完，管理员才在帝江号上醒来，故事正式从「复苏」开始。',0,'2026-11-15 14:03:40.333372');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (50,'endfield','e050','place','mid','极光圈','文明环带以北的危险区，铁誓军最前线','[\"极光圈\", \"极光圈地区\", \"极光禁区\", \"北方前线\"]','[\"极光圏\"]','极光圈是文明环带以北的危险区域，铁誓军驻守的最前线。极光圈之内，超域压倒现实，是真正的「禁区」。\n\n第一次天使战争爆发后的 24 小时里，大量锚点让天使的巨型集群摧毁了北方星门周围最初的城市，它们完全占据了北极地区，并可能以至今未知的手段引发了「塔卫二的极光」。\n\n铁誓军围绕北极圈构筑连绵堡垒与封锁线，为的就是不让那 24 小时重演。',0,'2026-11-15 14:03:40.333909');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (51,'endfield','e051','place','high','萨米维格','萨米诸部落最北的定居地','[\"萨米维格\", \"萨米之路\", \"萨米\", \"雪祀\"]','[\"萨米維格\"]','萨米维格在萨米语中意为「萨米之路」，是萨米诸部落在塔卫二的主要居住地，也作为团体名登记在《环带公约》中。这片偏远寒冷的土地是这颗卫星上最北端的大规模人类定居地，与铁誓军的要塞比邻。\n\n萨米人来塔卫二的方式很特殊：他们不是跟随科考团，而是在一头巨兽的背上穿越了时空的藩篱。这头巨兽是人类已知最大的巨兽个体之一，名字同样叫「萨米」，也被称为「祖灵之父」。\n\n巨兽萨米后来在战斗中陨落，身躯重构了当地环境，形成今天的萨米维格。大多数萨米人仍按古老传统生活，以「雪祀」术师首领为中心结成部落，由雪祀大会代表整体意志参与环带事务。志愿加入铁誓军的萨米部族战士，是铁誓军最重要、最稳定的兵源。',0,'2026-11-15 14:03:40.334398');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (52,'endfield','e052','place','low','熔炉要塞','铁誓军的兵工厂与要塞都市','[\"熔炉要塞\", \"遗产库\", \"旗队\", \"北方堡垒\"]','[\"熔爐要塞\"]','熔炉要塞是铁誓军封锁北极圈的连绵堡垒后方的心脏：兵工厂吞吐钢铁与重炮，遗产库保存着可追溯至泰拉结晶时代前的战争遗产。\n\n要塞都市承载了大量非军事人口，由来自文明环带的志愿者与军人家属构成。来自环带各地、以及在要塞中出生的军人结为「旗队」，以浴血的战旗传承不屈的战斗意志。\n\n对铁誓军的人来说，熔炉要塞不是一个地点，是一句誓言的后半句。',0,'2026-11-15 14:03:40.334862');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (53,'endfield','e053','place','mid','宏山环形山','天师府获赠的环形山','[\"宏山环形山\", \"宏山环\", \"环形山\", \"天师府驻地\"]','[\"宏山環形山\"]','宏山环形山是第一次天使战争后被发现的巨大环形山，被赠予天师府。它的地理条件十分适宜建设多种大型研究设施及农业水培设施，宏山科学院的总部与宏山城都在这里。\n\n到《环带公约》签订的几天前，宏山科学院正式挂牌成立；此后它成为塔卫二最大、最专业的科研复合体，满足着几乎整个文明环带的食品需求。\n\n环形山里有质量加速器一类的大型设施，也有大片水培农场——宏科院「既种粮又造枪」的名声，就是从这片地形里长出来的。',0,'2026-11-15 14:03:40.335359');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (54,'endfield','e054','place','mid','宏山城','宏山环形山下的城市，炎国后裔聚居','[\"宏山城\", \"宏山人\", \"炎国后裔\", \"宏山\"]','[\"宏山誠\"]','宏山城是宏山环形山下的大城，居民多是炎国后裔，也是陈千语长大的地方。城里有环带少见的稠密市井气：茶楼、面馆、夜市、擂台。\n\n宏山城的人对「天师」两个字有天然的敬意，也有一套自己的判断标准——先看你的手艺，再看你的出处。\n\n从宏山城出来的人常带着一点骄傲，也常带着一点「必须赢」的劲头；陈千语、庄方宜都属于这一类。',0,'2026-11-15 14:03:40.335840');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (55,'endfield','e055','place','high','武陵地区','宏科院治理侵蚀的重点地区','[\"武陵地区\", \"武陵科学发展区\", \"综合治理项目\", \"武陵全区\"]','[\"武陵地区\"]','武陵地区是宏山科学院开展侵蚀治理工程的重点地区，设有武陵科学发展区。第一次天使战争后，武陵的特大侵蚀裂隙就成了文明环带最棘手的问题之一。\n\n那处位于地质构造深处的大裂隙贯穿整个地区，是环带已探知范围内最大的超域裂隙；从裂隙起始点蔓延的侵蚀让环境恶化，自然水体被转化为液态侵蚀。\n\n塔罗斯历 132 年，宏科院科研考察团被派驻武陵，研发息壤、试图修复这片土地。二十年的研究与建设、巨大的牺牲之后，以息壤为基础的天师桩阵列终于把侵蚀潮控制在有限地理范围内。',0,'2026-11-15 14:03:40.336357');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (56,'endfield','e056','place','high','武陵城','武陵科学发展区唯一的大型定居点','[\"武陵城\", \"武陵\", \"天师城\", \"水利城\"]','[\"武陵誠\"]','武陵城是宏山科学院在武陵科学发展区的重要科研基地，也是该地区唯一的大型定居点，是环带监测超域活动、研究裂隙与侵蚀环境的最前沿。\n\n天师桩阵列与随处可见的水利设施是这座城市最突出的特征。人口主要由宏科院的天师、职农、职工及他们的家属构成。\n\n它的前身是塔罗斯历 132 年为推进甚大裂隙综合治理项目设置的科考站，最初只有天师与职工 113 人。142 年遏制裂隙主体的尝试失败，一场大规模侵蚀灾害吞没科考站、造成重大伤亡；这场灾难成了武陵城的起点——新的息壤技术、新的水利设施，以及一座在废墟旁诞生的新城市。',0,'2026-11-15 14:03:40.336955');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (57,'endfield','e057','place','high','武陵甚大裂隙','环带已知最大侵蚀裂隙，武陵的最大威胁','[\"武陵甚大裂隙\", \"甚大裂隙\", \"裂隙主体\", \"分支裂隙带\"]','[\"武陵甚大裂縫\"]','武陵甚大裂隙是位于武陵地区地下的特大侵蚀裂隙，是文明环带已探知范围内规模最大的侵蚀裂隙。\n\n它在地理空间上呈网状分布：一处极为活跃的裂隙主体，加上向周边延伸数十公里的分支裂隙带。裂隙带来的侵蚀已穿透并撕裂武陵地区地下的深层地质构造；地下水体被转化为液态侵蚀，涌上地表便成了「侵蚀潮」。\n\n塔罗斯历 142 年，武陵科考站的天师尝试用息壤切断裂隙主体与分支带的联系，准备周密却仍引发灾难：科考站及原型息壤设施在两小时内被侵蚀潮完全吞没。遗址就是今天的北部禁区。天师桩阵列控制住了液态侵蚀，但裂隙仍在扩张，随时可能再次发难。',0,'2026-11-15 14:03:40.337491');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (58,'endfield','e058','place','mid','应龙关','为甚大裂隙再爆发而建的关隘','[\"应龙关\", \"关隘\", \"土木天师\", \"关隘防线\"]','[\"应龍关\"]','应龙关是宏山科学院为限制甚大裂隙扩张而建的关隘，主体结构由土木天师设计，并结合息壤材料技术专门强化了针对侵蚀的防御构造。\n\n它采用的所有设计建造标准都基于一个假想场景：甚大裂隙再度爆发。必要时，宏科院会调用最高规格的应急力量，借巨兽权能进一步强化关隘的防御机能。\n\n北部禁区被封锁在应龙关之后；十年来，应龙特勤队在此长期驻守。',0,'2026-11-15 14:03:40.337975');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (59,'endfield','e059','place','mid','北部禁区','武陵科考站灾难遗址，被彻底封锁','[\"北部禁区\", \"科考站遗址\", \"禁区\", \"封锁区\"]','[\"北部禁區\"]','北部禁区是塔罗斯历 142 年灾难的遗址：武陵科考站与原型息壤设施在两小时内被裂隙爆发带来的侵蚀潮完全吞没，幸存者寥寥。\n\n宏科院投入全部应急力量，把受灾难影响的区域封锁在应龙关之后。十年来，北部禁区被彻底封锁，应龙特勤队长期驻守；武陵城兴建后，宏科院又用天师桩阵列等息壤技术产物，重新建立起对禁区内异常侵蚀现象的遏制体系。\n\n对武陵城来说，它是一道无法愈合的伤；对环带来说，它是一份用命换来的治理方案。',0,'2026-11-15 14:03:40.338537');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (60,'endfield','e060','place','high','清波寨','武陵城外傍水而生的小聚落','[\"清波寨\", \"水寨\", \"寨民\", \"悬空构造\"]','[\"清波寨\"]','清波寨是位于武陵城外的一处小型聚落，居民傍水而生，早在宏科院科研考察团到来之前便在武陵地区生活。\n\n层叠的悬空构造与简单的水利设施支撑着寨民的日常。寨民窃取抢夺武陵城物资的事件时有发生，但清波寨总体上仍能自给自足。\n\n地方史研究者认为，清波寨的建立可追溯到耻辱战争时期：那场不光彩的武装冲突让许多人对环带的未来感到悲观，这种情绪同样影响了建寨者——他们来到武陵，想在这颗陌生星球上重新寻找归宿。',0,'2026-11-15 14:03:40.339055');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (61,'endfield','e061','place','mid','祖泉','清波寨的天然水源，实为炎国水利装置','[\"祖泉\", \"净化之泉\", \"水竹铃\", \"泉水祭祀\"]','[\"祖泉\"]','祖泉是清波寨寨民对寨中一处天然水源的称呼，传闻它有净化侵蚀、驱散外来威胁的能力，是清波寨立寨的根基。祭祀与节庆都在泉边举行，泉边有水车，也放着寄托对逝者思念的水竹铃。\n\n少有人知的是，净化之力并非神迹，而源于泉底一座炎国水利装置。该装置由炎国天师于百余年前建造，通过把侵蚀与泉流分离来保持水源洁净。\n\n装置年代久远、无人维护，储污池里积聚的侵蚀濒临满溢，随时可能威胁地上的清波寨。最终，在一位知情寨民的恳请下，管理员以源石技艺将其彻底封停。',0,'2026-11-15 14:03:40.339532');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (62,'endfield','e062','place','low','藏剑谷','清波寨东南的山谷，传有秘库','[\"藏剑谷\", \"秘库\", \"秘库遗产\", \"剑冢\"]','[\"藏劍谷\"]','藏剑谷是位于武陵清波寨东南面的一处山谷。相传其中有一座秘库，埋藏着第一次天使战争前遗留的技术遗产。\n\n「藏剑」两个字既是地名，也是寨民对武艺传统的寄托——清波寨的先祖在建寨之初就研习炎国传统武艺，天资较高者会离寨游历，以求突破。\n\n秘库的传说至今没有定论。去藏剑谷的人，一半为遗物，一半为传说。',0,'2026-11-15 14:03:40.339997');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (63,'endfield','e063','place','mid','栖云林地','武陵深处的林地，天师桩与裂隙交错','[\"栖云林地\", \"林地\", \"桩阵\", \"林间裂隙\"]','[\"棲云林地\"]','栖云林地是武陵深处的一片林地，天师桩与裂隙在这一带交错，是第二章后期的重要战场。\n\n敌人会破坏天师桩制造裂隙，把超域力量引到地面；佩丽卡在这里判断出「超域被塑形成剑与墙壁」，管理员则要激活辅桩、重启天师桩，把裂口压回去。\n\n林地的湿气重，息壤粒子的散布与水体转化在这里都更活跃，走一趟要换两次滤芯。',0,'2026-11-15 14:03:40.340474');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (64,'endfield','e064','place','mid','谈剑堂','武陵的剑术旧地，陈千语受训处','[\"谈剑堂\", \"剑堂\", \"旧址\", \"堂前告别\"]','[\"談剑堂\"]','谈剑堂是武陵的一处剑术旧地，也是陈千语幼时受训剑艺的地方。堂里的毕业考核等级她一直没敢查，怕被师父拿去和母亲比较。\n\n第二章末尾，管理员一行人在谈剑堂旧址吊唁、告别，武陵的故事在这里收束成一句「余晖未却」。\n\n剑堂的旧规讲究「先修心，再修剑」；如今堂里冷清，旧规还在。',0,'2026-11-15 14:03:40.340965');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (65,'endfield','e065','place','mid','超域试验场','建在稳定裂隙旁的研究设施','[\"超域试验场\", \"试验场\", \"深度维持\", \"超域内部观测\"]','[\"超域试验場\"]','超域试验场是联盟工团在供能高地搭设的特殊试验场所，建在一条「天然稳定裂隙」旁边——较长时间内未观察到扩张、不易引发侵蚀的裂隙。\n\n自塔罗斯历 90 年起，工团已在这里陆续进行包括深度维持、超域内部观测等试验。\n\n第一章末尾，管理员与佩丽卡进入试验场，击败白垩界卫，为四号谷地这一阶段的追击画上句号。',0,'2026-11-15 14:03:40.341458');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (66,'endfield','e066','place','mid','源石森林','最初源石内化宇宙的信息脉络','[\"源石森林\", \"完整信息碎片\", \"内化宇宙\", \"析出\"]','[\"源石森林\"]','源石森林是「最初的源石」被污染后，其内化宇宙里仍保持完整的信息碎片所构成的脉络，被形容为腐化信息流中唯一能看清的一道无穷尽的光。\n\n在华法琳的解析中，一枚信息碎片的深度读数意外自发上升，从内化宇宙「析出」到现实空间——第一位再旅者就是这样抵达塔卫二的。\n\n再旅者们走出源石森林后，普遍对罗德岛和管理员表现出友好、合作的态度；华法琳后来主动探索这片森林，接回那些愿意来塔卫二的碎片。',0,'2026-11-15 14:03:40.341932');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (67,'endfield','e067','place','low','菈梵朵玛自由市','环带的自由市，商会活动频繁','[\"菈梵朵玛\", \"自由市\", \"碰碰杯杯\", \"环带城市\"]','[\"菈梵朵馬\"]','菈梵朵玛自由市是文明环带里的一座自由市，环塔商会在这里活动频繁，商会发言人曾表示很期待在菈梵朵玛接待终末地的客人。\n\n陈千语早年在菈梵朵玛的「碰碰杯杯」奶茶店打过三个月工——她自己的说法是「喝够了奶茶，就走了」。\n\n自由市不受单一势力管治，消息与货物都比别处流通得快；环带人谈生意、找人、躲人，都爱往这类地方去。',0,'2026-11-15 14:03:40.342385');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (68,'endfield','e068','place','low','玛尔斯波利斯','环带城市，出现在邮费抱怨里','[\"玛尔斯波利斯\", \"邮路\", \"城市\"]','[\"马尔斯波利斯\"]','玛尔斯波利斯是塔卫二上的一座城市，在环带的邮路抱怨里被提到：几本笔记寄到玛尔斯波利斯，邮费要五百金票。\n\n现有资料未确认它的位置、规模与管治方；只知道它通邮，且邮费不便宜。\n\n这类只出现在日常抱怨里的地名，恰恰是塔卫二生活质感的来源——城市不必上战场，也可以被记住。',0,'2026-11-15 14:03:40.342843');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (69,'endfield','e069','place','low','塞什卡','巢雕与商旅的来处，位置待核','[\"塞什卡\", \"商旅\", \"源地\", \"荒原\"]','[\"塞什喀\"]','塞什卡是军阀雅各布带出巢雕的地方——在裂地者尚未分裂的时代，他从塞什卡取得这种能吸收侵蚀、散播烟雾的巫术装置。\n\n商旅也会提到塞什卡：在昼雪的救援经历里，山洞避难所中挤着铁誓军军人、塞什卡商旅，甚至裂地者。\n\n现有资料未确认塞什卡的具体位置与政体；它更像一个「外面」的代称，凡是从更远处来的东西，都可能被说成来自塞什卡。',0,'2026-11-15 14:03:40.343413');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (70,'endfield','e070','place','low','沙海与荒地','环带之外的荒野地带，裂地者活动区','[\"荒地\", \"沙海\", \"荒野\", \"无人区\"]','[\"荒第\"]','荒地与沙海是环带之外的大片无人地带：风沙、盐碱、被侵蚀啃过的岩层，以及散落的旧据点。裂地者的多数活动都在这一类地形里。\n\n在荒地上行走的规矩是「跟着水走，别跟着路走」——路会断，水不会凭空消失。\n\n荒地里也有活人：商队、拾荒者、逃出环带的流民，以及不想被任何人登记在册的人。',0,'2026-11-15 14:03:40.344041');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (71,'endfield','e071','person','high','管理员','终末地工业领导者，失忆十年后苏醒','[\"管理员\", \"Endministrator\", \"帝江号总控\", \"石棺\"]','[\"管理員\"]','管理员是终末地工业的领导者。十年前亲手完成帝江号的建造，随后进入石棺沉睡；十年后由佩丽卡唤醒，记忆只剩轮廓。\n\n帝江号的总控中枢、协议核心的部署权、集成工业系统的现场调用权都在管理员手上；环带依据公约在危机时重启终末地工业的全文明环带特别权限，恢复他的优先通行权与现场处置权。\n\n管理员与协议源石、协议空间有超出常人的关联：只有他能自由进入协议空间。\n\n管理员不解释过去，也不喜欢被盘问。佩丽卡对干员们的交代是：别把「石棺里的那个人」当成传说，把他当成一个刚回岗的同事。',0,'2026-11-15 14:03:40.344592');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (72,'endfield','e072','person','high','佩丽卡','终末地监督，管协议技术与帝江号','[\"佩丽卡\", \"Perlica\", \"监督\", \"终末地发言人\"]','[\"佩莉卡\", \"佩丽佳\"]','佩丽卡是终末地工业的监督，也是终末地的官方发言人之一，主要负责管理和推进协议源石技术的开发与应用，同时承担帝江号的管理工作。黎博利族。\n\n她儿时在灾难中幸存，和其他失去家庭的孩子一同接受了管理员与终末地的庇护；不到两年，足迹遍布这颗星球的大小城市，之后加入研发中心，在协议技术开发与应用上取得重大突破，被正式任命为「监督」，开始掌舵帝江号。\n\nM3 的评价是：这个职位是因为佩丽卡才存在，别搞错先后顺序。她同时也是危机处理小组成员，常陪小队在第一线；人事助理对此颇有微词，但拦不住。\n\n她曾失去管理员一次，也看着情同姐妹的莱西娅离开帝江号；她把这些都收在「监督」这张脸后面，只在极少数人面前露出来。',0,'2026-11-15 14:03:40.345162');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (73,'endfield','e073','person','high','陈千语','危机处理小组核心剑手','[\"陈千语\", \"Chen\", \"双剑\", \"危机处理小组\"]','[\"陳千语\", \"陈千語\"]','陈千语是终末地危机处理小组的核心干员，龙族，出身宏山城。幼时在谈剑堂受训剑艺，后来在应龙特勤队待过一年多，又在多地短暂驻留，最后由佩丽卡监督私人渠道招募进终末地。\n\n她惯用双剑，机动性极强；动机陈述一栏只写了「就是想来，缘分到了」，人事助理为此重新构建了一套审核标准。\n\n她几乎不可动摇地乐天，是帝江号上派对名单的第一个名字，能在五分钟内让最内向的干员开口。佩丽卡说，是因为陈能够给人带来安全感。\n\n她只睡三个小时也能满场跑，打坐冥想时其实在打瞌睡。',0,'2026-11-15 14:03:40.345674');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (74,'endfield','e074','person','high','狼卫','狼群氏族的终末地干员，隐匿与铳械专家','[\"狼卫\", \"卡特洛\", \"卢皮诺\", \"狼群代表\"]','[\"狼衛\"]','狼卫，全名卡特洛·狼卫·卢皮诺，裂地者狼群氏族成员，鲁珀族，矿石病感染者。他作为狼群代表与终末地工业达成合作，后经佩丽卡推荐加入特种技术部门。\n\n他观察力与应变能力极强，习惯单独行动，擅长隐秘工作，精通铳械与肉搏，能把任何物件当武器——哪怕一支钢笔。\n\n他对武器改装的热忱让武库工程师头疼：当着工程师的面改完新枪，说「我认为这样更好用」。他的说法是，成熟的猎手理应挑选最趁手的猎具，够不上就改装到最趁手。\n\n他与妹妹洛茜是十几年前碾骨截杀中仅存的幸存者；他离群的原因与那场劫难，一直讳莫如深。',0,'2026-11-15 14:03:40.346164');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (75,'endfield','e075','person','mid','洛茜','狼卫之妹，狼群氏族出身的年轻干员','[\"洛茜\", \"狼卫的妹妹\", \"狼群猎手\", \"路易家双胞胎\"]','[\"洛西\"]','洛茜是狼卫的妹妹，狼群氏族的年轻猎手，后来加入终末地成为干员。\n\n她与哥哥一样，是十几年前碾骨截杀中仅存的幸存者。狼卫极少回家，她就在生日前后念叨「礼物到了人没到」；族里的鲁斯特叔叔替她抱不平，狼卫只回一句「她知道我今天回来」。\n\n她在猎场与路易家的双胞胎一起长大，性子与哥哥像得出奇——同一窝的鲁珀，骨子里一模一样。',0,'2026-11-15 14:03:40.346646');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (76,'endfield','e076','person','high','赛希','寂语修会派驻终末地的信息工程师','[\"赛希\", \"塞拉菲娜\", \"修会修士\", \"推荐人\"]','[\"塞希\", \"赛西\"]','赛希，全名塞拉菲娜·赛希，寂语修会修士，萨卡兹族，矿石病感染者。因终末地与寂语修会合作开展源石信息技术研究，受修道院长伏龙达推荐前来供职。\n\n她现阶段参与帝江号协议源石网络的搭建与系统集成等信息工程事务。她住在历代服务器专家工作的机房里，见不到阳光，常年冷气降温；想领特种电子作业设备，得去她那里拿。\n\n她内敛、虔诚，把专业当信仰、把信仰当专业；会在交谈中突然问起机械的意识信号如何编码，然后礼貌地道歉。\n\n四年前她只是来进修，一抵达就主动投身帝江号修缮。佩丽卡说，这也许是寂语修会成员望着历史与未来时天然形成的责任感。',0,'2026-11-15 14:03:40.347123');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (77,'endfield','e077','person','high','莱万汀','再旅者干员，记忆原型是史尔特尔','[\"莱万汀\", \"Laevatain\", \"史尔特尔\", \"再旅者干员\"]','[\"莱万丁\", \"莱万婷\"]','莱万汀是再旅者干员，萨卡兹族，由管理员直接引荐、经罗德岛授权，以管理员直属干员身份入职终末地。\n\n她被强烈的「愿望」驱使来到塔卫二：解答「我是谁」。她的记忆原型是史尔特尔——但除非她主动提起，不要在她面前做任何比较。\n\n她说话毫不修饰，那不是敌意，是她最真诚的态度。真正让她不耐烦时，别劝她冷静，给冰淇淋更快。\n\n她随身带着一枚需要武库工程师定期检查维护的环；她只说过一句：「让我去尽量多的地方，那些可以留下尽量多回忆的地方。」',0,'2026-11-15 14:03:40.347604');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (78,'endfield','e078','person','high','洁尔佩塔','再旅者信使，记忆原型是安洁莉娜','[\"洁尔佩塔\", \"Gelperta\", \"安洁莉娜\", \"信使\"]','[\"洁尔佩达\", \"杰尔佩塔\"]','洁尔佩塔，沃尔珀族，经罗德岛引荐加入终末地，隶属特种技术部门。来报到前，她已经在塔卫二游历了两年，作为信使帮过许多人。\n\n她是再旅者，记忆原型是安洁莉娜。她身上大部分衣物都是红色，却能绽放出许多色彩；帝江号上几乎每个人都收到过她捎带的礼物。\n\n她能用法术让雨珠停在半空；给孩子们讲天上的故事，用糖纸拼出他们的样子。华法琳交给她的第一封信，她走了很久才送到——因为每个地方都想去。',0,'2026-11-15 14:03:40.348103');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (79,'endfield','e079','person','high','伊冯','瓦伊凡族工程师，研究超域与侵蚀装置','[\"伊冯\", \"Yvonne\", \"全频超域抑稳自动机\", \"工程师\"]','[\"伊馮\", \"依冯\"]','伊冯，瓦伊凡族，经联盟工团的克劳推荐给安德烈，以「特殊人才引进」渠道进入终末地特种技术部门，负责对超域、侵蚀及其相关装置「全频超域抑稳自动机」的研究。\n\n很多人说她「叛逆」，人事助理不同意：大部分人跟不上她的思考速度，才显得她难以协作。她对长年研究形成的个人风格相当自信，并非蓄意违抗规范，而是本能抗拒对思考方式的干涉。\n\n她把家里的图书室亲手烧了——父亲说，既然你已经决定好自己的道路，我们就把那些东西烧掉吧。她烧完又用无人机把书提了出来：只是口味不同，为什么一定要全毁。',0,'2026-11-15 14:03:40.348609');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (80,'endfield','e080','person','high','庄方宜','武陵管代兼息壤新材项目负责天师','[\"庄方宜\", \"庄天师\", \"武陵管代\", \"息壤新材\"]','[\"莊方宜\", \"庄方仪\"]','庄方宜，麒麟族，宏山科学院天师，武陵科学发展区管代，兼任息壤新材项目负责天师，经宏科院推荐与终末地合作进行裂隙相关研究。\n\n她是公认的工作狂：每天把日程排满，再一件件完成；实验室里堆满生活用品，武陵城的家却整洁如新到像没人住过。被强制休假时，她会在沙滩上来回踱步，最后瘫在床上念「实验，我得去实验室」。\n\n她从不和人聊自己。与她共事的人走进风暴中心，发现那里什么都没有。母亲庄含青在她年幼时病逝，那之后她几乎不再开口谈家事。\n\n武陵科考站事故后她临危受命管理安置点，表现让宏科院高层把重建重任交给了年纪尚轻的她。',0,'2026-11-15 14:03:40.349082');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (81,'endfield','e081','person','high','汤汤','清波寨话事人，终末地驻寨办事处负责人','[\"汤汤\", \"清波寨话事人\", \"汤汤券\", \"竹编花环\"]','[\"湯湯\"]','汤汤，菲林族，清波寨成员兼主要话事人，因私人原因加入终末地工业，现担任终末地驻清波寨办事处负责人。矿石病感染者，十年前清波寨与武陵天师冲突时感染。\n\n她开朗、直率、不拘小节，对一切充满热情与好奇。第一次上帝江号就拍着人事助理的面板喊「三头铁面公」，给人戴竹编花环，还邀请对方「跟清波寨混」。\n\n她对事态的觉察力和敏感度不输任何人：清波寨后续建设里，她以寨民为首要考量，粗中有细地照顾到每一位老少病残。\n\n她自称「姑奶奶的脑袋装不了太多事儿」，但帝江号因为她变得更有生气——陈千语说，她像一把永不熄灭的火。',0,'2026-11-15 14:03:40.349544');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (82,'endfield','e082','person','mid','艾尔黛拉','再旅者地质专家，记忆原型是艾雅法拉','[\"艾尔黛拉\", \"艾雅法拉\", \"地质专家\", \"多利先生\"]','[\"艾尔戴拉\"]','艾尔黛拉，卡普里尼族，来自罗德岛的地质研究专家，对火山相关地质灾害有深入研究，现已入职终末地，常年在外实地勘探。\n\n她是再旅者，记忆原型是艾雅法拉。源石重塑了再旅者的身躯，抹去了病痛——她能听见风穿过的低语，看清岩石上细微的裂纹。\n\n在侵蚀灾区的安置所里，一个少女对她说「你不懂」；那一晚她追着一只叫多利先生的毛茸茸生物，找到一架积满灰尘的钢琴，弹了莱塔尼亚的曲子。少女后来说：我还是痛，但你弹琴的时候，我会不想离开这个世界。',0,'2026-11-15 14:03:40.350008');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (83,'endfield','e083','person','mid','提弗洛斯','再旅者，萨米传说与野外生存的行家','[\"提弗洛斯\", \"提丰\", \"萨米传说\", \"野外生存\"]','[\"提弗洛丝\", \"提佛洛斯\"]','提弗洛斯，萨卡兹族，来自罗德岛的再旅者干员，在追寻萨米失落传说的旅途中与管理员偶遇，后经管理员本人邀请加入终末地。\n\n她冷静沉稳得远超年龄，但旺盛的好奇心与不合时宜的探究眼神暴露了孩子心性。她能连问三个小时，然后把人事助理记成「三个脑袋，无所不知，有问必答」。\n\n北方的监测工作靠她：暴风雪摧毁营地后，她带着一整只兽腿赶到，升起篝火，用一个下午在原始环境里搭出四人容身的木屋。导航设备瘫痪时，大家靠她极准的预感与危险擦肩而过。\n\n有人猜是独眼巨人教会她洞见未来；更可能的答案是萨米人与自然相处的方式——置身其中，才能感知自然的呼吸。',0,'2026-11-15 14:03:40.350477');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (84,'endfield','e084','person','mid','昼雪','再旅者救援专家，记忆原型是极光','[\"昼雪\", \"极光\", \"救援专家\", \"制冰施术单元\"]','[\"画雪\", \"昼雪\"]','昼雪，乌萨斯族，隶属罗德岛，在罗德岛与终末地工业合力进行的多次救援行动中以救援专家身份解决难题，现派驻终末地开展合作。\n\n她是再旅者，记忆原型是极光。工程学背景给了她强大支撑：极端环境下救出铁誓军军人与极地商旅，规划并实施救援，选择应对策略。\n\n她在帝江号上以「雪中送炭」出名：送一瓶陈醋让食堂的糖醋兽肉出得了锅，教大家雪地过弯与急救步骤。伊冯对她的制冰施术单元赞不绝口。\n\n她长期在侵蚀环境下救援，医疗部门建议在定期体检中增加相关检测。她自己倒是很豁达，唯一让食堂紧张的是：她一驻舰，甜品区就只剩标签。',0,'2026-11-15 14:03:40.350951');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (85,'endfield','e085','person','high','聂菲斯','碾骨氏族头领，操纵侵蚀与雾火','[\"聂菲斯\", \"碾骨头领\", \"拥抱超域\", \"赐福雾火\"]','[\"聂菲絲\", \"聂非斯\"]','聂菲斯是塔卫二裂地者中最具危险性的头目，碾骨氏族崛起的核心人物。她的出身、经历、性格与理念通通是谜，唯一确定的是：她对遇见的任何一个阵营都深怀敌意。\n\n她带来「雾火」，一种与侵蚀有关、能致幻、有毒、又能短时强化身体机能的火焰；围绕雾火，碾骨建立起比其他氏族更坚实的组织。她让部众吸收侵蚀、崇拜超域，宣称「拥抱超域吧，现在，它已经臣服于我」。\n\n她以人心为柴薪、以仇恨作火种：利用阮一丧兄后的复仇冲动搅乱清波寨，在四号谷地要塞煽动「弃子」演说，又亲手用「影子」布兰娜清理氏族旧派。\n\n她拒绝向任何胜者俯首：「要么是主宰源石的管理员，要么是前文明的残渣基石。但我拒绝。」她刺杀阿达希尔、夺走阿莱克琉斯的协议源石，留下话：下一次，塔卫五见。',0,'2026-11-15 14:03:40.351402');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (86,'endfield','e086','person','high','阿达希尔','能撕开甚大裂隙的敌对者，身份存疑','[\"阿达希尔\", \"撕开裂隙\", \"心脏阴谋\", \"第纳尔金币\"]','[\"阿达希爾\", \"阿达西尔\"]','阿达希尔是四号谷地与武陵行动中多次出现的敌对者，能撕开甚大裂隙、直取首墩的巨兽心脏；剧情显示他「早已放弃肉体凡胎」，一次「死」并非终局。\n\n他与聂菲斯曾是合作者，最终被聂菲斯亲手刺杀——她手持协议源石，刺穿祀留下的水墨能量禁制，毁去他当时的肉身，然后转身离去。他问「你是什么时候背叛我们的」，她答「背叛？你们的计划如此顺利，何来背叛？」。\n\n他曾把一枚来自泰拉萨尔贡的古老第纳尔金币亲手送给管理员——那是他最喜欢的一枚。这枚金币说明他并非只会破坏的人。\n\n他的身份、目的与「前文明残渣」一类的归类，现有资料未完全确认，引用时保留余地。',0,'2026-11-15 14:03:40.351856');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (87,'endfield','e087','person','mid','罗丹','聂菲斯麾下干部，谷地要塞决战拦截者','[\"罗丹\", \"聂菲斯干部\", \"要塞拦截\", \"狼\"]','[\"罗丹\"]','罗丹是聂菲斯麾下的干部之一，在谷地要塞决战中负责拦截管理员一行，称狼卫为「狼」，并试图将其消灭。\n\n他是碾骨氏族被改造的一批战力之一：体型庞大、能改变气体密度，靠强化后的躯体碾压反抗者。\n\n「水火不容」里，罗丹向聂菲斯来报「他的计划失败了」；聂菲斯只回了三个字：「那开始吧。」',0,'2026-11-15 14:03:40.352323');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (88,'endfield','e088','person','mid','阮一','清波寨动乱的推手，因丧兄而复仇','[\"阮一\", \"丧兄之痛\", \"丧兄复仇\", \"祖泉决战\"]','[\"阮壹\"]','阮一是清波寨动乱中的关键人物。他在丧兄之后被聂菲斯利用，复仇的冲动被引向清波寨内部，酿成寨民与武陵城之间的再一次流血。\n\n佩丽卡一针见血：聂菲斯很乐于利用他的冲动，甚至不需要亲自动手就能控制清波寨。\n\n祖泉之战中，阮一被击败；但他的残党仍在，追击持续了很长一段路。',0,'2026-11-15 14:03:40.352784');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (89,'endfield','e089','person','mid','阿莱克琉斯','武陵甚大裂隙的敌对者，协议源石被夺','[\"阿莱克琉斯\", \"协议源石被夺\", \"甚大裂隙战场\", \"敌对者\"]','[\"阿莱克琉斯\"]','阿莱克琉斯是武陵甚大裂隙一役中的敌对者。他的协议源石被聂菲斯夺走——她用这枚源石刺穿禁制、毁去阿达希尔的肉身。\n\n第二章后期，管理员一行人在武陵甚大裂隙与其交战；这一战同时收束了聂菲斯的追击线与武陵的裂隙危机。\n\n他与「基石」一类的先史文明存在是否同源，现有资料未确认，不宜直接等同。',0,'2026-11-15 14:03:40.353262');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (90,'endfield','e090','person','mid','埃尔埃格尼斯','序章北极点的终局级敌对存在','[\"埃尔埃格尼斯\", \"序章终局\", \"唤醒生命\", \"北极终点\"]','[\"埃尔埃格尼丝\", \"埃尔艾格尼斯\"]','埃尔埃格尼斯是序章「冷启动」的终局级敌对存在，在北极点（远征尽头）的终点被远征队击败，随后「唤醒生命」。\n\n它出现的场景本身就带着终局意味：巨塔、花圃、「英雄的臂膀」、进入「过去」。序章的战斗结束后，管理员才在帝江号上醒来。\n\n关于它的来历与性质，现有资料只给到「终局级存在」这一层，不宜自行补设定。',0,'2026-11-15 14:03:40.353712');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (91,'endfield','e091','person','high','M3','终末地精英干员，零号委托执行人','[\"M3\", \"零号委托执行人\", \"精英干员\", \"语音备忘录\"]','[\"M三\", \"M3干员\"]','M3 是终末地的精英干员，也是「零号委托」的执行人之一。这趟回帝江号，就是为了确认管理员的状态。\n\n按佩丽卡的说法，让一个失忆的人尝试学会游泳自救有点强人所难；但她还是选择相信管理员——「失忆症状意味着我们没有太多机会了」。\n\nM3 是再旅者事务的知情人之一，也是当年在管理员与华法琳之间递话、默许抢救性研究的人。她留给佩丽卡档案的，是一段语音备忘录。',0,'2026-11-15 14:03:40.354223');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (92,'endfield','e092','person','high','华法琳','罗德岛时任领袖，再旅者计划的推动者','[\"华法琳\", \"罗德岛领袖\", \"再旅者之父\", \"最初的源石\"]','[\"华法林\", \"华法琳\"]','华法琳是罗德岛时任领袖。在管理员本人与 M3 的默许下，她对被污染的「最初的源石」展开抢救性研究，发现与信息碎片交流的方法，接回那些愿意来塔卫二的信息碎片。\n\n她为再旅者设计了整套进入塔卫二世界的流程。接回再旅者的行为近乎等同于创造生命，她独自承担这个责任，偶尔会向终末地方的知情人发泄压力。\n\n她反复提起自己是如何靠多年人生阅历「迅速」说服自己的——关于年数，她先后说过 500 年、300 年，目前称 20 年。罗德岛和终末地都愿意相信森林里看见的那道光。',0,'2026-11-15 14:03:40.354710');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (93,'endfield','e093','person','mid','莱西娅','前终末地干员，独自狩猎超域活动','[\"莱西娅\", \"前终末地干员\", \"狩猎超域\", \"老熟人\"]','[\"莱西雅\", \"莱西娅\"]','莱西娅曾是终末地干员，也是佩丽卡「情同姐妹」的旧识，后来离开帝江号，与佩丽卡分道扬镳。\n\n她在进行一场只属于她的狩猎：对她说，超域活动就是猎物留下的踪迹。她这么做是为了完成一个约定——一个与管理员亲口做的约定。\n\n四号谷地源石发电站，她出手阻止了裂地者；佩丽卡对管理员介绍她时，从一声迟疑的「莱西娅」迅速转成疏离的「老熟人」，又主动补了一句「你和她亲口做的约定」。',0,'2026-11-15 14:03:40.355213');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (94,'endfield','e094','person','mid','秦茳尺','终末地物资调度员，代号幸运萝卜','[\"秦茳尺\", \"幸运萝卜\", \"物资调度员\", \"秦工程师\"]','[\"秦江尺\", \"秦茳尺\"]','秦茳尺，代号「幸运萝卜」，终末地工业物资调度员，常驻四号谷地。她负责启用调度券系统、协调本地物资供需，并提醒管理员警惕有人利用调度体系囤货居奇。\n\n她认为形象工程很重要：紧急状况发生时，终末地有义务参与协调当地资源，帮助身处困境的人。\n\n她嘴硬心软。安德烈受伤那回，她一边抱怨这老头「逞英雄」「把工作成果看得比老命重要」，一边催他赶紧回中控塔。',0,'2026-11-15 14:03:40.355688');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (95,'endfield','e095','person','mid','安德烈','集成工业系统总工程师，技术权威','[\"安德烈\", \"集成工业系统总工程师\", \"原型机\", \"胖大鸟\"]','[\"安得烈\", \"安德列\"]','安德烈是终末地常驻技术专家、集成工业系统总工程师，枢纽区的修复与原型机工作由他负责。立体传送带的设计出自他手。\n\n基地解围时，旧工厂区被锚点击中，他独自跑回去保护朋友留下的原型机，因冲击昏迷；醒来第一件事是问原型机怎么样，然后认出管理员，激动地提起十年课题终于突破。\n\n他提到普契尼和波波夫——那两位到最后还在遗憾，没能把方案亲手交给管理员。察觉管理员失忆后，他沉默了一会儿，说「这不公平」。\n\n陈千语管他叫「胖大鸟」；他崴了脚还坚持先不见秦主管，怕挨骂。',0,'2026-11-15 14:03:40.356203');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (96,'endfield','e096','person','mid','诀','应龙特勤队队长，首墩自我封印者','[\"诀\", \"应龙特勤队队长\", \"自我封印\", \"心脏封印\"]','[\"诀队长\"]','诀是应龙特勤队队长，在首墩一役中以自我封印阻止阿达希尔破坏巨兽心脏。\n\n佩丽卡对她的评价很微妙：明明年龄相差不大，却能从她身上感觉到一种特别的气质。陈千语则在这位队长身上看到了应龙特勤队的往事。\n\n她的装备原理与息壤近似；借用巨兽心脏是当时唯一可行的办法，她做了那个决定。',0,'2026-11-15 14:03:40.356726');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (97,'endfield','e097','person','low','弭弗','武陵巡卫指挥，防卫战中的地面指挥','[\"弭弗\", \"巡卫指挥\", \"武陵巡卫\", \"防卫战\"]','[\"弥弗\"]','弭弗是武陵巡卫指挥，负责城防与地面行动部署。搜捕聂菲斯与阿达希尔时，佩丽卡先向她确认行动细节，再问「终末地能帮上什么忙」。\n\n武陵城防卫战中，巡卫与天师、寨民战力共同顶住碾骨的攻势；战后，弭弗认可了终末地的协助。\n\n她说话直，办事更直；在她那里，客气不如一张标清楚的部署图。',0,'2026-11-15 14:03:40.357248');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (98,'endfield','e098','person','low','奚墨','被困首墩的天师，后留守巨兽心脏','[\"奚墨\", \"武陵天师\", \"首墩天师\", \"留守心脏\"]','[\"奚默\"]','奚墨是武陵的天师，在首墩被天使围攻时由佩丽卡带队解围。\n\n他后来自愿留守，守护巨兽心脏——那既是任务，也是他对诀那份决断的回应。\n\n天师的本分在他身上体现得很朴素：该守的东西守住，该留的人留下。',0,'2026-11-15 14:03:40.357757');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (99,'endfield','e099','person','mid','雅各布·迈森','荒地军阀，裂地者名号的创造者','[\"雅各布·迈森\", \"荒地军阀\", \"裂地者之父\", \"天使战争英雄\"]','[\"雅各布麦森\", \"雅各布·梅森\"]','雅各布·迈森是荒地军阀，曾经的天使战争英雄。拓荒者抵达塔卫二后的第五十九年，他把手下规模庞大的匪帮命名为「裂地者」，带人占据一片源石培植地，建立了塔卫二有史以来最危险的武装掠夺者团体。\n\n他从塞什卡带出了巢雕；在他割据一方的初期，身边就有「火山」查查祖父的身影。\n\n他最终被文明环带剿灭，但「裂地者」这个词留了下来，成为所有蔑视文明秩序的匪帮武装分子的统称。',0,'2026-11-15 14:03:40.358219');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (100,'endfield','e100','person','low','彦宁','武陵天师，做防护与探测装置','[\"彦宁\", \"防护装置\", \"探测装置\", \"深度读数上升\"]','[\"彦寧\"]','彦宁是武陵的天师，负责防护装置与探测装置的研发，长期关注武陵深度读数的上升趋势。\n\n她与白霜一起推进防护装置的迭代：从实验室样品到能带进裂隙边缘的实战版本，中间隔着无数次失败与重做。\n\n在武陵，天师不需要被塑造成英雄——把读数压下去一点点，就是一年。',0,'2026-11-15 14:03:40.358780');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (101,'endfield','e101','person','low','白霜','武陵科研人员，与彦宁共同迭代防护装置','[\"白霜\", \"装置迭代\", \"科研人员\", \"武陵科研\"]','[\"白霜\"]','白霜是武陵的科研人员，与彦宁共同推进防护装置的迭代。\n\n他不太出现在台前，多数时间在实验室里改设计、测材料；武陵人记得的是装置好不好用，不是谁画的图。\n\n这类角色是塔卫二科研体系的底色：没有名字，但每一道防线都压着他们的手。',0,'2026-11-15 14:03:40.359398');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (102,'endfield','e102','person','mid','索斯','谷地避难所管事，难民据点的组织者','[\"索斯\", \"避难所管事\", \"安置所\", \"庇护所\"]','[\"索斯\"]','索斯是四号谷地避难所的管事，负责难民的安置与据点建设。谷地要塞遇袭后，难民潮涌向通道，索斯在其中维持秩序。\n\n建立据点一役，管理员一行人为难民部署次级核心、连接传送带与精炼炉、制造并放置铳械塔；索斯提供的是另一种支持——知道谁在哪儿、谁还缺什么。\n\n他说话不绕弯，也不轻易许诺；在开拓区，这已经算很高的信用。',0,'2026-11-15 14:03:40.359934');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (103,'endfield','e103','person','low','阿伯莉','为保护学生牺牲的教师，采石场以她命名','[\"阿伯莉\", \"采石场\", \"教师\", \"塔罗斯历75年\"]','[\"阿伯丽\"]','阿伯莉是塔罗斯历 75 年天使集群袭击四号谷地时为保护学生而牺牲的教师。\n\n大批锚点坠落于谷地外围，一小股天使穿过防线出现在学校附近。阿伯莉疏散学生，天使穷追不舍；学生撤到待建隘口（今采石场入口附近）时，她攀上高处，用施工现场的爆炸物炸塌山体，挡住了天使，也把自己留在了那场爆炸里。\n\n联盟工团把即将竣工的采石场命名为「阿伯莉采石场」；后来采石场挖出神秘金属而停工，那件东西被命名为「阿伯莉之石」。',0,'2026-11-15 14:03:40.360475');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (104,'endfield','e104','person','mid','布兰娜','碾骨氏族的刺客「影子」，聂菲斯的刀','[\"布兰娜\", \"影子\", \"碾骨杀手\", \"影子刀\"]','[\"布兰纳\"]','布兰娜，绰号「影子」，碾骨氏族的刺客。传闻氏族合并之初，她曾向聂菲斯发起挑战，惨败；聂菲斯没有取她性命，而是让她加入自己麾下。\n\n四号谷地多桩裂地者遇袭现场，狼卫判断这些都是「内部肃清」：一个灵巧、狡猾的杀手，用伏击、诱骗等最省力的方式清理掉预定目标。\n\n她的刀法是「熟悉」的刀法：精准刺入护甲缝隙，还要额外补上几刀。调查结论是，她不是「火山」查查的同谋，而是聂菲斯手里的那把刀。',0,'2026-11-15 14:03:40.360988');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (105,'endfield','e105','person','low','庄含青','庄方宜之母，宏山科学院医生','[\"庄含青\", \"庄方宜母亲\", \"宏山医生\", \"讣告\"]','[\"庄含清\"]','庄含青是宏山科学院的医生，庄方宜的母亲，因病在宏山第一医院逝世，享年 42 岁。\n\n讣告登在《宏山晚报》第八版。灵堂那天，年幼的庄方宜一言不发地离开了；舅舅庄长青找了她一天，最后是小姨庄岱青陪着她。\n\n母亲去世后，她几乎不再开口谈家事——这成了庄天师「从不和人聊自己」的起点。',0,'2026-11-15 14:03:40.361479');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (106,'endfield','e106','person','low','伏龙达','寂语修会修道院长，推荐赛希来终末地','[\"伏龙达\", \"修道院长\", \"修会总部\", \"推荐赛希\"]','[\"伏龙達\"]','伏龙达是寂语修会的修道院长。终末地与寂语修会合作开展源石信息技术研究时，他推荐赛希前来供职。\n\n「穹顶坍塌」事故后，伏龙达与三个教派领袖紧急会面商议处置——肇事者是赛希，她重绘大教堂代码穹顶，让大修道院网络崩溃了 0.836 秒。\n\n他处理这类事的方式很寂语：先议事，再定论，最后把结论登在《早安阿碎评论》上。',0,'2026-11-15 14:03:40.362051');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (107,'endfield','e107','person','mid','马丁·马文·马伦','终末地人事助理，多份人事简述的签名人','[\"马丁·马文·马伦\", \"人事助理\", \"终末地人事\", \"马伦先生\"]','[\"马丁马伦\", \"马文马伦\"]','马丁·马文·马伦是终末地工业的人事助理，多份干员人事简述的签名人。他负责入职调查、背景审核与心理测评转介。\n\n他写人事简述有一种不动声色的幽默：会认真讨论「就是想来，缘分到了」是否符合战略目标，也会为一个机器人不该写诗而向读者道歉。\n\n他对佩丽卡的评价很克制：她不该总是陪着小组成员在第一线冒险；就算她继续驳回申请，他还是会督促她重新评估风险。',0,'2026-11-15 14:03:40.362550');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (108,'endfield','e108','person','low','卡拉德','终末地安全专家，负责安全与情报','[\"卡拉德\", \"终末地安全专家\", \"情报\", \"武器检查\"]','[\"卡拉德\"]','卡拉德是终末地的安全专家，管安全与情报。佩丽卡曾匆忙去训练室找他，一本正经地请教「要怎么和她在乎的管理员正常相处」，把他吓了一跳。\n\n他答应过佩丽卡要绝对保密，尤其是对管理员；他的原话是：我的嘴可是最严的，这是职业操守。\n\n莱万汀随身那枚环，由武库工程师定期检查维护——这类安全条目也要经他的手。',0,'2026-11-15 14:03:40.363069');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (109,'endfield','e109','person','low','弧光','帝江号精英干员，赛希的交谈对象','[\"弧光\", \"值班干员\", \"帝江号值班\", \"赛希的朋友\"]','[\"弧光干员\"]','弧光是帝江号的精英干员。她与赛希的相处不算复杂：赛希会告诉她一些她从没注意到的细节，比如「人寓居在各自的语言中」——够她琢磨一天。\n\n在帝江号的日常里，她属于那种不太出声、但总在的人。\n\n关于她的更多资料，现有语料未展开；引用时只写这一层。',0,'2026-11-15 14:03:40.363528');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (110,'endfield','e110','event','high','第一次天使战争','塔罗斯历5至15年的人类与天使之战','[\"第一次天使战争\", \"天使战争\", \"塔罗斯历5年\", \"北极决战\"]','[\"第一次天使戰爭\"]','第一次天使战争指塔罗斯历 5 年至 15 年发生在人类与以天使为主的敌对势力之间的战争；塔罗斯历 142 年之前的文献里记述的「天使战争」与它指的是同一场战争。以塔罗斯历 11 年为界，可分为前后两部分。\n\n战争前期以天使造成的大规模灾害和人类方的混乱为标志：战争爆发 24 小时内，突然出现的大量锚点让天使的巨型集群淹没并摧毁了人类在北方星门周围建立的最初城市，它们完全占据北极地区，并可能以未知手段引发了「塔卫二的极光」。随后六年，残存人类不断向南迁移，不断丧失技术产物。\n\n塔罗斯历 11 年，当时的【管理员】协助剩余人类势力完成重整，人类开始能有效抵御天使进犯；15 年的一次重大军事行动之后，天使在南方的活动得到遏制。这一时期还包括巨兽萨米的到来、萨米子民掀起的「狂猎之日」、铁誓军建军。\n\n对人类来说，主要的天使灾害与战争行为在 15 年末结束，因此这一年被一些人视为战争结束年；另一些人则认为，17 年文明环带的建立才意味着彻底终结。',0,'2026-11-15 14:03:40.363976');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (111,'endfield','e111','event','high','第二次天使战争','139年被放逐者再叩门扉，战争迫近','[\"第二次天使战争\", \"被放逐者\", \"塔罗斯历139年\", \"再叩门扉\"]','[\"第二次天使戰爭\"]','塔罗斯历 139 年，被放逐者们再次叩响门扉，第二次天使战争近在咫尺。\n\n第一次天使战争里，管理员带领新生的同盟发起反击，把威胁放逐进超域；代价是开拓基地全面失陷，源石与管理员严重受损。被放逐的东西并没有消失，只是被关在门外。\n\n如今北方有天使之外的信号，南方有超域的足迹，裂地者又学会了操控天使。四方会议重启终末地工业的全文明环带特别权限，就是为了这件事。',0,'2026-11-15 14:03:40.364464');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (112,'endfield','e112','event','mid','耻辱战争','环带与全面内战擦肩而过的武装冲突','[\"耻辱战争\", \"全面内战\", \"公约缔结\", \"悬崖勒马\"]','[\"恥辱战争\"]','「耻辱战争」是文明环带与全面内战擦肩而过的一场不光彩的武装冲突。泰拉人险些用自己的武器杀死自己。\n\n管理员留下的种子及时萌发，人们在悬崖边缘止住脚步，《环带公约》正式缔结；随后数十年，繁荣的年代拉开帷幕。\n\n这场战争的后遗症比战果更长：清波寨的建寨者就是对环带未来感到悲观的一批人，他们离开城市，去武陵另寻归宿。',0,'2026-11-15 14:03:40.364972');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (113,'endfield','e113','event','low','狂猎之日','第一次天使战争后期萨米子民的行动','[\"狂猎之日\", \"萨米子民\", \"巨兽萨米\", \"战争后期\"]','[\"狂猎日\"]','「狂猎之日」是第一次天使战争后期的重大事件之一，由萨米子民掀起；同一时期还有巨兽萨米的到来与铁誓军的建军。\n\n萨米人跟随祖灵之父穿越时空的藩篱来到塔卫二，在战争最艰难的时刻加入了人类一方。\n\n关于这一天的具体经过，现有语料只给到「战争后期的重大事件」这一层；细节需回原文核。',0,'2026-11-15 14:03:40.365452');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (114,'endfield','e114','event','high','四方会议','三大阵营与终末地的秘密会晤','[\"四方会议\", \"帝江号会议\", \"特别权限\", \"U3会晤\"]','[\"四方會議\"]','四方会议是第一章进程Ⅳ的关键节点：联盟工团、环塔商会与宏山科学院联合来讯，希望与终末地工业进行秘密会晤，会议在帝江号上以远程形式召开。\n\n佩丽卡以终末地监督身份主持报告，说明四号谷地行动概要，提出「零号委托」遭到针对性阻挠的研判。会议通报了北方天使之外的信号、南方超域的足迹等异常。\n\n会议依据《环带公约》重启终末地工业的全文明环带特别权限，恢复管理员的优先通行权与现场处置权；会后，宏科院请求优先支援武陵科学发展区。\n\nM3 也在此时现身帝江号，透露自己是零号委托执行人之一，并警示聂菲斯可能只是吸引注意力的棋子。',0,'2026-11-15 14:03:40.365916');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (115,'endfield','e115','event','high','管理员苏醒','沉睡十年后，管理员在帝江号醒来','[\"管理员苏醒\", \"进程复苏\", \"十年沉睡\", \"唤醒\"]','[\"管理員苏醒\"]','管理员在帝江号上苏醒，距他进入石棺、沉睡过去已经十年。醒来时记忆破碎，佩丽卡告诉管理员：这里是帝江号，她是终末地的监督，在他熟悉这里之前负责照顾他。\n\n三个标准日后，佩丽卡带管理员参观帝江号，介绍这艘船的历史，指出管理员曾是终末地的领导者、带大家挽救了帝江号；她展示了随身携带的协议源石，并揭示「零号委托」的委托人正是管理员本人。\n\n联络员菲奥娜报告四号谷地出现紧急危机后，佩丽卡当即决定提前出发，放弃十天后出发的原计划，进行有风险的无引导紧急降落。',0,'2026-11-15 14:03:40.366406');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (116,'endfield','e116','event','high','四号谷地袭击','碾骨与天使同时来袭，锚点被规律投放','[\"四号谷地袭击\", \"碾骨进攻\", \"锚点规律出现\", \"紧急广播\"]','[\"四号谷地襲擊\"]','四号谷地袭击是第一章的直接起因：碾骨氏族的大群裂地者武装分子与大量天使同时来袭。锚点有规律地出现在工团各站点上空——这不是巧合，敌人在一定程度上掌握了操控天使的技术。\n\n袭击发生七分钟后，一条署名「联盟工团」的紧急广播以文本形式发到各主要终端；它后来在工团设置的ЭКОП应答器处被回收。并非所有相关人员都及时看到了这条信息，也有人在传递它的过程中牺牲。\n\n工团各站点立刻执行安全预案，但枢纽区基地仍与帝江号失去联络，出现极强的天使信号；佩丽卡与管理员因此提前启程。',0,'2026-11-15 14:03:40.366874');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (117,'endfield','e117','event','high','基地解围','第一章首个任务，破锚点救安德烈','[\"基地解围\", \"旧工厂区\", \"地下锚点\", \"地下实验室\"]','[\"基地解圍\"]','枢纽区基地与帝江号失去联络并出现极强天使信号，佩丽卡与管理员提前启程查看。\n\n在旧工厂区，裂地者趁乱渗透，锚点核心藏在地下实验室。管理员破坏锚点、击败碾骨劫掠者与首领，救出独自回来保护原型机的总工程师安德烈。\n\n随后与秦茳尺会合，为基地提供支援；裂地者的渗透与锚点坠落只是开始，真正的问题是基地的供电与运转。',0,'2026-11-15 14:03:40.367356');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (118,'endfield','e118','event','high','谷地重启','启动协议共振塔，恢复枢纽区供电','[\"谷地重启\", \"协议共振塔\", \"协议核心首次部署\", \"供电\"]','[\"谷地重啟\"]','谷地重启要解决的问题是供电：启动协议共振塔能恢复枢纽区基地的运转，但塔需要电。\n\n管理员在基地外的预留地点首次部署协议核心，从核心开始电力运输、为中继器供电，再把电力送到协议共振塔。\n\n这是集成工业系统与协议核心第一次在剧情里完整亮相：放核心、拉电、送电、开机，一整套动作定义了此后所有据点建设的节奏。',0,'2026-11-15 14:03:40.367847');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (119,'endfield','e119','event','mid','重整旗鼓','修复源石副产物中心，回收原型机资料','[\"重整旗鼓\", \"源石副产物中心\", \"军械库\", \"便携源石矿机\"]','[\"重整旗鼓\"]','重整旗鼓是基地解围后的恢复工作：源石副产物中心大量需要修复，采集源矿、放置精炼炉与供电桩、生产晶体外壳，一点点把生产链接回来。\n\n同一条线上还有回收原型机技术资料、部署便携源石矿机、爆破军械库入口救出武库工程师。\n\n这一阶段没有大反派，只有清单；清单越短，基地越像能住人的地方。',0,'2026-11-15 14:03:40.368330');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (120,'endfield','e120','event','mid','西行入谷','前往谷地要塞，与裂地者专家会合','[\"西行入谷\", \"谷地要塞遇袭\", \"桥头防线\", \"裂地者专家\"]','[\"西行入谷\"]','西行入谷时，谷地要塞遭裂地者袭击。管理员一行人在桥头工事与「裂地者专家」会合，修复桥梁升降开关、为供电终端供电，打通前往要塞的路。\n\n也就是在这一段，狼卫在谷地通道向管理员报到并入队——他带来的是裂地者的情报，以及一个提醒：铳口不能朝着队友。\n\n桥修好了，路才通；路通了，才有后面的庇护之所。',0,'2026-11-15 14:03:40.368828');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (121,'endfield','e121','event','mid','庇护之所','深入谷地通道，接触难民群体','[\"庇护之所\", \"谷地通道\", \"难民\", \"阿吉\"]','[\"庇護之所\"]','庇护之所是谷地通道里的一段：管理员一行人寻找深入推进的方法，救出卡贾的妹妹阿吉，与索斯交谈，接触难民群体。\n\n难民不是背景板：他们有名字、有伤病、有谁还没回来。索斯在混乱里维持秩序，靠的是知道谁在哪儿、谁还缺什么。\n\n这一段之后，「据点」这个词才有了具体重量。',0,'2026-11-15 14:03:40.369308');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (122,'endfield','e122','event','mid','建立据点','为难民建据点，部署次级核心与防线','[\"建立据点\", \"次级传输\", \"铳械塔\", \"难民据点\"]','[\"建立據點\"]','建立据点是为难民做的事：部署次级核心、连接传送带与精炼炉、制造并放置铳械塔，把一个能住、能守、能生产的地方搭起来。\n\n随后管理员进入未知的协议空间，探查四号谷地奇怪的源石反应——据点不只是墙，还要知道墙外是什么。\n\n在塔卫二，给一群人建据点，等于替他们向这颗星球宣一个不太正式的誓。',0,'2026-11-15 14:03:40.369757');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (123,'endfield','e123','event','mid','踏破雾火','地下管道突入，破巢雕驱雾','[\"踏破雾火\", \"通风管道\", \"摧毁巢雕\", \"驱散烟雾\"]','[\"踏破霧火\"]','踏破雾火是绕后的一步：借地下通风管道深入裂地者聚集地，破坏碾骨氏族建造的巢雕，以驱散拦路的烟雾。\n\n巢雕一倒，烟雾散去，源石设备重新可用；这是管理员一方第一次正面拆掉碾骨的战略设施。\n\n「雾火」不是普通烟雾——吸入的人会不适、幻听、幻视，碾骨成员却能在其中被强化。拆巢雕，等于拆掉对方的主场。',0,'2026-11-15 14:03:40.370238');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (124,'endfield','e124','event','high','要塞决战','谷地要塞决战，击败罗丹追击聂菲斯','[\"要塞决战\", \"上层追击\", \"聂菲斯现身\", \"要塞内层\"]','[\"要塞決戰\"]','要塞决战是第一章进程Ⅰ的收束：管理员一行人深入谷地要塞，击败罗丹，乘电梯前往要塞上层追击聂菲斯。\n\n聂菲斯在决战中现身，展示对超域的掌控，宣告「人与人的战争开始了」。她称管理员「一个救世主，一个暴君」，这句称呼暗示两人之间存在某种过去。\n\n要塞夺回了，但聂菲斯走了；从四号谷地开始的漫长追击，一直追到武陵。',0,'2026-11-15 14:03:40.370677');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (125,'endfield','e125','event','mid','修缮进展','恢复帝江号联络，管理员接管总控','[\"修缮进展\", \"协议同步器\", \"总控中枢\", \"联络恢复\"]','[\"修繕進展\"]','修缮进展解决的是「回家」：管理员此前对通讯节点的修复生效，枢纽区基地恢复与帝江号的联系。\n\n管理员受召前往中控塔，用协议同步器协助校准地天协议传送，成功返回帝江号；在赛希引导下巡视制造舱与会客室，正式接管帝江号总控中枢的控制权限。\n\n站在舰桥上说了句「回来的感觉真好」，又补了一句「抱歉，我现在这么说好像有点奇怪」。佩丽卡回答：能听见你这句话，我们追随的就不再是一个虚影了。',0,'2026-11-15 14:03:40.371123');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (126,'endfield','e126','event','mid','矿脉断章','深入矿脉源区，抵达世代摇篮','[\"矿脉断章\", \"矿脉深处\", \"踏足矿脉\", \"摇篮遗迹\"]','[\"矿脈断章\"]','矿脉断章是第一章进程Ⅲ的一段：管理员一行人穿越研究园、下行山道，进入矿脉源区，最终踏足世代摇篮。\n\n这一路上，园区、诡楼、山道、矿脉各有各的麻烦；真正的收获是弄清了四号谷地的能源从哪来、又为什么差点断掉。\n\n矿脉断章之后，才有「临战休整」与进程Ⅳ的正面反击。',0,'2026-11-15 14:03:40.371632');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (127,'endfield','e127','event','mid','三位一体','星体三条残肢重组的天使，再败于摇篮','[\"三位一体\", \"星体残肢\", \"世代摇篮再战\", \"天使重组\"]','[\"三位一體\"]','「三位一体」是「星体」成百上千条肢体中的寥寥三根，在锚点的激活下重新组合成的天使，于世代摇篮再次被管理员击败。\n\n它证明了一件事：被毁掉的天使不会被彻底杀死，只要锚点还在、残骸还在，它就能被重新组装起来。\n\n这也是为什么开拓队的第一原则始终是「先找锚点」。',0,'2026-11-15 14:03:40.372106');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (128,'endfield','e128','event','high','神秘信号','追查超域信号，牵出莱西娅','[\"神秘信号\", \"协议通讯信号塔\", \"旧识\", \"发电站信号\"]','[\"神秘信號\"]','神秘信号是第一章进程Ⅳ的转折：伊冯侦测到微弱超域能量信号，管理员接通协议通讯信号塔配合验证、测试临时扫描组件，最终把信号定位到供能高地的源石发电站。\n\n发电站有裂地者袭击的痕迹，信号却消失了；管理员遇到阻止裂地者的莱西娅——佩丽卡介绍她是老熟人，曾为终末地干员，独自狩猎超域是为完成与管理员的约定。\n\n回去的路上，三大阵营的紧急联络到了；帝江号召开四方会议，四号谷地的故事被接到整个环带的危机上。',0,'2026-11-15 14:03:40.372576');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (129,'endfield','e129','event','high','初探武陵','启程武陵，误入清波寨后入城见庄方宜','[\"初探武陵\", \"误入清波寨\", \"水车\", \"管代合作\"]','[\"初探武陵\"]','初探武陵是第二章的开端：管理员一行人启程前往武陵，误入清波寨，得汤汤相助；重启水车、循密道入城，面见武陵管代庄方宜，并达成合作。\n\n武陵不是四号谷地。这里有天师、有水系、有寨民与城之间的旧账；天师桩阵列和随处可见的水利设施，是这座城市最突出的特征。\n\n合作谈成的那一刻，终末地在武陵的协议核心部署也排上了日程。',0,'2026-11-15 14:03:40.373024');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (130,'endfield','e130','event','high','清波寨动乱','寨内动乱，营救汤汤，祖泉击败阮一','[\"清波寨动乱\", \"营救汤汤\", \"祖泉之战\", \"寨内动乱\"]','[\"清波寨動亂\"]','清波寨动乱起于人心：阮一丧兄之后，被聂菲斯利用其复仇冲动，把矛头引向清波寨内部。\n\n管理员一行人营救汤汤，在祖泉与阮一决战并将其击败，随后追击其残党。\n\n动乱之后，汤汤成了清波寨的话事人，也成了终末地驻清波寨办事处负责人；寨子里那些习武的、沉默的、背井离乡的人，各自有了去处。',0,'2026-11-15 14:03:40.373615');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (131,'endfield','e131','event','high','水火不容','首墩之战，诀自我封印护住巨兽心脏','[\"水火不容\", \"首墩之战\", \"心脏守卫战\", \"诀的封印\"]','[\"水火不容\"]','水火不容是第二章进程Ⅳ的高潮：阿达希尔破坏首墩巨兽心脏的计划被诀以自我封印阻止。\n\n首墩一带曾堆积大量天使残骸，佩丽卡靠「沉积酸」判断地形；她指出阿达希尔可能掌握了更高层次的「操纵」侵蚀的手段，能撕开裂隙、塑形超域。\n\n管理员判断「该轮到聂菲斯登场了」；罗丹来报计划失败，聂菲斯只回一句：「那开始吧。」',0,'2026-11-15 14:03:40.374248');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (132,'endfield','e132','event','mid','巨兽心脏之战','首墩深处，围绕巨兽心脏的守卫战','[\"巨兽心脏\", \"自由意志\", \"守护心脏\", \"首墩深处\"]','[\"巨獸心臟\"]','巨兽心脏之战围绕首墩深处的巨兽心脏展开。借用巨兽心脏是当时唯一可行的办法；诀的封印、奚墨的留守、天师桩的辅助，都是为了那颗心脏不被夺走。\n\n这一战的关键不是打赢谁，而是「守住」——心脏一旦失守，武陵的防线与巨兽权能都会崩塌。\n\n「自由意志」是这一段剧情的注脚：守的人自己决定留下。',0,'2026-11-15 14:03:40.374835');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (133,'endfield','e133','event','high','武陵城防卫战','聂菲斯攻城，天师桩阵列与总桩守卫战','[\"武陵城防卫战\", \"浪白风初起\", \"总桩\", \"超域火焰\"]','[\"武陵城防衛戰\"]','武陵城防卫战（浪白风初起）是第二章进程Ⅴ：聂菲斯率碾骨氏族与叛逃寨民集结，目标是摧毁息壤堰、撕开甚大裂隙。她降下超域火焰淹没阵列，天师与巡卫苦战不休。\n\n庄方宜以总桩核心为饵诱敌深入；管理员修复三处阵列核心后，在总桩与聂菲斯正面相逢。战斗中，超域重塑了她的躯体，她一边打一边用广播撩拨：「累了吗？过去的你可没有这么惹人怜惜」「来取出我的心脏吧」。\n\n侵蚀潮攻破总桩，息壤防线受损，但武陵城守住了；佩丽卡在战后说，城里已经变成这样了，都会恢复原样的。',0,'2026-11-15 14:03:40.375495');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (134,'endfield','e134','event','mid','墙崩因隙','武陵城墙与裂隙的危机，庄方宜的抉择','[\"墙崩因隙\", \"武陵危机\", \"管代抉择\", \"裂隙扩张\"]','[\"牆崩因隙\"]','墙崩因隙讲的是「墙」：武陵城的防线与甚大裂隙之间的脆弱平衡，以及庄方宜在这种平衡里的抉择。\n\n城外侵蚀让这位管代疲于奔命；她的应对方式不是等，而是把能提前做的事全部做完。\n\n这一段没有大战场，只有倒计时：裂隙在扩，息壤在耗，人在撑。',0,'2026-11-15 14:03:40.376083');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (135,'endfield','e135','event','high','长风破浪','聂菲斯刺杀阿达希尔，夺协议源石离去','[\"长风破浪\", \"余晖未却\", \"刺杀阿达希尔\", \"塔卫五见\"]','[\"長風破浪\"]','长风破浪（余晖未却）是第二章进程Ⅶ：聂菲斯以突袭者身份来到被囚禁的阿达希尔面前，手持协议源石，趁其不备刺穿祀留下的水墨能量禁制，毁去他当时的肉身，然后无视其自燃的身体转身离去。\n\n阿达希尔质问「你是什么时候背叛我们的」，她只回：「背叛？你们的计划如此顺利，何来背叛？」她明确宣告自己的道路：无论谁赢了，幸存者都要向胜者俯首称臣，要么是主宰源石的管理员，要么是前文明的残渣基石——「但我拒绝」。\n\n她夺取了阿莱克琉斯的协议源石，宣称「我们的暴力不属于任何人了」，并让阿达希尔托话：聂菲斯完成了约定，下一次，塔卫五见。',0,'2026-11-15 14:03:40.376571');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (136,'endfield','e136','event','mid','归途与谈剑','武陵善后，谈剑堂吊唁与告别','[\"归途\", \"谈剑问迹\", \"吊唁\", \"物非人是\"]','[\"歸途\"]','归途与谈剑是第二章进程Ⅶ的收束：武陵善后、谈剑问迹、物非人是、异乡归人、拨云见日，最后落在「归途」。\n\n管理员一行人在谈剑堂旧址吊唁、告别；武陵的伤口没有完全愈合，但人已经开始往回走。\n\n「余晖未却」四个字既是任务名，也是这一段的气质：仗打完了，光还留在地上。',0,'2026-11-15 14:03:40.377050');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (137,'endfield','e137','event','mid','内部肃清','碾骨旧派被聂菲斯借刀清理','[\"内部肃清\", \"多桩遇袭\", \"火山查查\", \"影子布兰娜\"]','[\"內部肅清\"]','内部肃清是四号谷地发生的一连串裂地者遇袭案：断头台盖比、鬼火维奇尔、血眼撒萨罗先后被杀，现场都像是同一个人下的手。\n\n调查结论是「影子」布兰娜所为，而她从一开始就不是「火山」查查的同谋。查查想把这些游离于「赐福」边缘的人聚起来掀翻聂菲斯，聂菲斯就用布兰娜这把刀，把叛徒一次清干净。\n\n这些人的失败，代表着「旧」碾骨正在被驱逐出「新」碾骨。聂菲斯是个优秀的统治者——这对环带来说是好消息，也仅仅是目前。',0,'2026-11-15 14:03:40.377536');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (138,'endfield','e138','event','mid','息壤问世','140年，天师与巨兽代理人造出息壤','[\"息壤问世\", \"塔罗斯历140年\", \"天师与代理人\", \"原型息壤设施\"]','[\"息壤問世\"]','塔罗斯历 140 年，在一众天师与一位巨兽代理人的共同努力下，名为「息壤」的新型源石材料问世。\n\n经过多次独立测试，活性化的息壤能够消耗自身，把液态侵蚀逐步中和为自然水体。终末地工业作为合作方，参与了原型息壤设施的建造。\n\n两年后的灾难证明，材料本身不是答案——怎么用、用在哪里，才是。',0,'2026-11-15 14:03:40.378062');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (139,'endfield','e139','event','high','武陵科考站灾难','142年用息壤切裂隙失败','[\"武陵科考站灾难\", \"塔罗斯历142年\", \"两小时吞没\", \"封锁遗址\"]','[\"武陵科考站災難\"]','塔罗斯历 142 年，宏山科学院驻武陵科考站的天师们尝试利用息壤遏制甚大裂隙的扩张趋势。这次尝试经过周密准备，但仍引发灾难性后果：科考站及原型息壤设施在两小时内被裂隙爆发带来的侵蚀潮完全吞没。\n\n宏科院在之后的救援行动中付出巨大代价，幸存者仍然寥寥。宏科院投入全部应急力量，把受灾区域封锁在应龙关之后——那片遗址就是如今的北部禁区。\n\n这场灾难改写了武陵的技术路线：从「集中息壤强行闭合裂隙」转向「天师桩阵列对侵蚀潮做针对性治理」。武陵城就是在废墟旁建起来的。',0,'2026-11-15 14:03:40.378543');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (140,'endfield','e140','rule','high','超域实验禁令','公约严禁现实与超域的物质交换实验','[\"超域实验禁令\", \"物质交换实验\", \"活体实验\", \"批文\"]','[\"超域實驗禁令\"]','《环带公约》严格限制现实空间与超域之间的物质交换实验，绝大部分相关活体实验被禁止。\n\n理由写在档案里：物质从超域进入现实空间时，会在现实空间中产生动态侵蚀。活体实验等于拿人当引信。\n\n合法的研究走两条路：一是像工团那样在天然稳定裂隙旁建超域试验场，做深度维持与内部观测；二是像宏科院那样借巨兽权能与息壤材料做工程化治理。两条都要批文。',0,'2026-11-15 14:03:40.379007');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (141,'endfield','e141','rule','mid','协议传送规矩','协议传送需授权与定位，不能随意使用','[\"协议传送\", \"传送授权\", \"协议传送点\", \"定位\"]','[\"协议傳送\"]','协议传送不是免费的：单次能承载的人员与物资高度受限，还要调用具有高度危险性的超域能量，因此每一次传送都要授权、要定位。\n\n特种技术部门的干员通常配一枚协议源石用于辅助定位；没有约定的坐标，传送点不会为你打开。\n\n在战区，协议传送点往往是第一优先的争夺目标——谁掌握传送，谁就掌握增援与撤退。',0,'2026-11-15 14:03:40.379467');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (142,'endfield','e142','rule','mid','开拓区通行','进出开拓区要报备与授权，物资走调度','[\"开拓区通行\", \"通行报备\", \"区域授权\", \"物资协调\"]','[\"开拓區通行\"]','进开拓区要报备：人数、装备、目的地、预计返回时间，缺一项都可能被拦在检查站。带武器进环带城市同样要报备。\n\n区域内的物资协调走调度券。终末地的调度员会在授权后启用系统，并提醒：调度是协调手段，不阻碍正常的经济活动；拿它囤货居奇是另一回事。\n\n开拓区的通行证不是护身符。真出了事，来救你的不是那张纸，是名单上记得你的人。',0,'2026-11-15 14:03:40.379959');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (143,'endfield','e143','rule','mid','据点建设规矩','先核心、再供电、再防线、最后住人','[\"据点建设\", \"核心区域\", \"防线\", \"分级核心\"]','[\"據點建設\"]','建据点的顺序基本固定：先落协议核心，划定集成核心区域；再接电力与传送；再布铳械塔、围墙一类的防线；最后才是住处、厨房与医务。\n\n先住人后设防，在开拓区等于把人摆在砧板上。工团与终末地的现场手册都把顺序写死了。\n\n据点建成后要留一条退路：桥、密道、或一条能走的河道。塔卫二没有哪座据点是一次建好、永不放弃的。',0,'2026-11-15 14:03:40.380437');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (144,'endfield','e144','rule','high','职业与元素','干员的稀有度、职业、元素','[\"职业\", \"元素\", \"稀有度\", \"编成口径\"]','[\"職業與元素\"]','终末地的干员档案里，会记【稀有度】【职业】【元素】这几项编成字段；例如五星、近卫、物理。\n\n元素分五类：灼热、寒冷、电磁、自然、物理。它描述的是这名干员作战时主要依靠的能量形态，不是阵营，也不是信仰。\n\n职业按作战定位划分，常见的近战突击定位会标「近卫」。这些字段属于编成口径，便于调度与配队，不要把它们当成世界观里的阶级或血统。',0,'2026-11-15 14:03:40.380912');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (145,'endfield','e145','rule','mid','裂地者的规矩','氏族的旧规矩与聂菲斯的新教义并存','[\"裂地者规矩\", \"氏族传统\", \"赐福\", \"弱肉强食\"]','[\"裂地者的規矩\"]','裂地者不认环带的法。氏族内部有自己的规矩：家族、团结、头狼的权威、对「正统」的执念。\n\n聂菲斯带来了另一套：赐福、雾火、拥抱超域。旧派认为这是亵渎，新派认为这是力量；两套规矩在同一个氏族里并行，谁也不好过。\n\n对外，裂地者的规矩很朴素：能抢就抢，抢不过就谈，谈不拢就打。唯一的例外是狼群——他们谈秩序，也守秩序。',0,'2026-11-15 14:03:40.381406');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (146,'endfield','e146','rule','mid','出勤与名单','出勤点名，回来再点一次，少一个就回头','[\"出勤名单\", \"点名\", \"带回\", \"伤亡\"]','[\"出勤與名單\"]','出勤前点名，回来再点一次。少一个名字，队伍会回头——这条不写在公约里，但在终末地、工团、铁誓军都一样管用。\n\n名单不只是纪律，也是记忆：安德烈说，哪怕人忘记了，数据和设备也不会忘。名单是另一种「设备」。\n\n在开拓区，一句「我回来带你」比任何契约都重。',0,'2026-11-15 14:03:40.381913');
REPLACE INTO `worldbook` (`id`, `world_slug`, `source_id`, `kind`, `priority`, `title`, `semantic`, `keys`, `fuzzy`, `body`, `is_constant`, `updated_at`) VALUES (147,'endfield','e147','term','high','寂语修会','承拉特兰信仰的技术研修组织','[\"寂语修会\", \"三大教派\", \"会话派\", \"重现派\", \"阐释派\"]','[\"寂语修會\", \"寂语\"]','寂语修会是继承了拉特兰信仰传统的技术研修组织，以一座移动的大修道院作为总部。一个多世纪以来，修士们致力于修复第一次天使战争中失落的泰拉技术，调查与发掘塔卫二可能存在的前文明遗迹，并为人们提供精神引导。\n\n修会积累了大量受《环带公约》认可的技术专利，但只用其中一小部分维持自身运作，绝大部分成果在文明环带范围内无偿共享。\n\n内部按拉特兰信仰形成三大教派：会话派重拾源石微电子技术，帮助各方重建现代通信网络，便携终端、无人机乃至帝江号的总控系统都离不开他们；重现派是手持重铳、身着重甲的武装修士，守护圣殿并参与先史遗迹发掘；阐释派把信仰放在首位，治愈星门崩溃造成的长久精神创伤，通过精神引导与公共慈善重建人与人的联系。',0,'2026-11-15 14:03:40.382388');
